      "q": "Câu 6 (K117 37HMU tr.28 Câu 1 & tr.18 Câu 7). Đặc điểm nào sau đây thuộc cơ chế 'Mất ức chế tiếp xúc' (Loss of contact inhibition) của tế bào ung thư, NGOẠI TRỪ:",
