      "hint": "Gợi ý: Ức chế tiếp xúc là hiện tượng các tế bào bình thường ngừng phân chia và di chuyển khi tiếp xúc sát nhau; mất ức chế tiếp xúc liên quan đến mất kết dính tế bào, tăng sinh chồng chất và tiết enzyme tiêu chất căn bản.",
      "exp": "Theo bài giảng Quá trình sinh bệnh ung thư (Bộ môn Ung thư ĐHYHN): Ở mô bình thường, khi các tế bào phân chia lấp đầy khoảng trống và chạm vào nhau sẽ kích hoạt tín hiệu 'ức chế tiếp xúc' làm ngừng phân bào. Ở tế bào ung thư, hiện tượng MẤT ức chế tiếp xúc gồm: (1) Giảm hoặc mất các phân tử kết dính bề mặt tế bào (như E-cadherin), làm tế bào tách rời nhau; (2) Tiếp tục phân chia chồng chất lên nhau vô tổ chức; (3) Tiết ra các enzyme tiêu đạm (protease, collagenase, MMPs) phá hủy màng đáy và cấu trúc nâng đỡ mô để xâm lấn. Ngược lại, việc ngăn cản tế bào lympho T gắn vào tiêu diệt tế bào u thuộc về 'Cơ chế trốn thoát hệ thống miễn dịch' (nhờ bộc lộ PD-L1 hoặc giảm trình diện kháng nguyên MHC lớp I).",
