      "exp": "Theo Giáo trình Ung thư học Đại học Y Hà Nội (Bài Quá trình sinh bệnh ung thư): Cơ chế sinh ung thư gồm 3 nhóm chính: (1) Cơ chế ở mức độ phân tử / Gen (hoạt hóa gen sinh ung thư - Oncogene, bất hoạt gen ức chế khối u - Tumor suppressor gene như p53, Rb, và đột biến gen sửa chữa ADN); (2) Cơ chế ở mức độ Tế bào (rối loạn kiểm soát chu kỳ tế bào, rút ngắn chu kỳ phân bào, mất ức chế tiếp xúc, bất tử hóa nhờ telomerase và giảm chết tế bào theo chương trình - Apoptosis); (3) Cơ chế Miễn dịch / Cơ thể (suy giảm khả năng giám sát miễn dịch). Không có khái niệm 'Cơ chế mô học'.",
