      "q": "Câu 10 (S3.7 K118 Câu 10 & K117 Câu 20 & tr.21 Câu 18). Theo số liệu GLOBOCAN năm 2020, ở Việt Nam tổng số ca mới mắc ung thư trong năm là 182.563 ca, tổng dân số là 97.757.118 người. Công thức tính Tỷ lệ mới mắc thô (Crude Incidence Rate) chuẩn trong dịch tễ học ung thư là:",
