      "exp": "Theo Giáo trình Ung thư học Đại học Y Hà Nội (Bài Dịch tễ học ung thư): Tỷ lệ mới mắc (Incidence rate) biểu thị số trường hợp mới mắc bệnh ung thư xuất hiện trong một quần thể xác định trong khoảng thời gian 1 năm, được tính trên 100.000 dân theo công thức: Tỷ lệ mới mắc = (Tổng số ca mới mắc trong năm [x] / Tổng dân số trung bình trong năm [n]) × 100.000. Với số liệu năm 2020: (182.563 / 97.757.118) × 100.000 ≈ 186,75 / 100.000 dân. (Tương tự với biến thể đề tr.11 Câu 23: 126.000 ca / 97 triệu dân → 126.000 / 97.000.000 × 100.000).",
