      "exp": "Theo Giáo trình Ung thư học ĐHYHN: Tỷ lệ mắc toàn bộ (Prevalence - P) bao gồm cả số ca mới mắc trong năm và số bệnh nhân đã mắc từ các năm trước hiện vẫn đang còn sống. Khi quần thể ổn định, công thức tính là: P = I × D (trong đó I là tỷ lệ mới mắc hàng năm trên 100.000 dân, D là thời gian sống thêm trung bình tính bằng năm). Do đó: P = 19,2 × 2 = 38,4 / 100.000 dân (hoặc nếu đề cho I = 18,2 thì P = 18,2 × 2 = 36,4 / 100.000 dân). Lưu ý bẫy: Tuyệt đối không chọn đáp án có ký hiệu '%' (38,4%).",
      "ref_label": "Giáo trình Ung thư học Đại học Y Hà Nội & Phân loại AJCC 8th Edition"
