        "C. Ung thư nguyên bào võng mạc (Retinoblastoma) (hoặc U sắc tố màng bồ đào/võng mạc nội nhãn di truyền)",
        "D. Ung thư biểu mô tế bào vảy của da (Squamous cell carcinoma - SCC)"
