      "exp": "Theo Giáo trình Ung thư học ĐHYHN: Tia cực tím (UV, đặc biệt là UVB bước sóng 280–320 nm) trong ánh nắng mặt trời tác động trực tiếp lên da gây tổn thương ADN (tạo các cầu nối thymine/pyrimidine dimer), là nguyên nhân hàng đầu gây ra 3 loại ung thư da vùng tiếp xúc ánh nắng: Ung thư biểu mô tế bào đáy (BCC), Ung thư biểu mô tế bào vảy (SCC) và Ung thư tế bào hắc tố (Melanoma). Trong khi đó, Ung thư võng mạc (U nguyên bào võng mạc - Retinoblastoma) là ung thư nhãn cầu ở trẻ nhỏ do đột biến gen ức chế khối u Rb1 (nhiễm sắc thể 13), không phải do tia UV gây ra.",
