      "exp": "Theo Giáo trình Ung thư học ĐHYHN: Virus Epstein-Barr (EBV) là tác nhân virus sinh ung thư ở người có liên quan mật thiết nhất với Ung thư vòm mũi họng (đặc biệt là thể ung thư biểu mô không biệt hóa - Undifferentiated carcinoma phổ biến tại miền Nam Trung Quốc và Việt Nam), ngoài ra còn liên quan đến U lympho Burkitt ở trẻ em châu Phi, U lympho Hodgkin và một tỷ lệ nhỏ ung thư dạ dày.",
