      "exp": "Đính chính cực kỳ quan trọng theo Bảng 5.1 (trang 38, Handout S3.7 Tập 1 - Đại học Y Hà Nội): Giáo trình chia thuốc hóa chất có khả năng gây ung thư thành 2 cột riêng biệt:\n• Cột 1 - Gây ung thư ở ĐỘNG VẬT: Adriamycin, Cisplatin, Dacarbazin, Mitomycin C, Nitrogen mustard, Procarbazin, Uracil mustard.\n• Cột 2 - Đã chứng minh gây ung thư ở NGƯỜI (IARC 1988): Gồm 6 thuốc nhóm Alkyl hóa là Busulphan, Chlorambucil, Cyclophosphamid, Melphalan, Methyl-CCNU và Treosulphan.\nDo đó, khi đề thi hỏi chất được IARC 1988 công bố gây ung thư trên NGƯỜI trong 4 chất (Bleomycin, Treosulphan, Mitomycin C, Nitrogen mustard), đáp án chuẩn xác theo đúng bảng trong sách ĐHYHN là B. Treosulphan (hoặc Busulphan ở biến thể có Busulphan). Nhiều bản review cũ của sinh viên khoanh nhầm 'Nitrogen mustard' do không tra Bảng 5.1 trang 38!",
