      "q": "Câu 21 (S3.7 K118 tr.4 & K118 37HMU tr.24 Câu 2). Thể mô bệnh học thường gặp nhất (chiếm tỷ lệ cao nhất tại Việt Nam và vùng dịch tễ Á Đông) của Ung thư vòm mũi họng là:",
