        "A. Ung thư biểu mô vảy sừng hóa (WHO týp I)",
        "B. Ung thư biểu mô không biệt hóa (Undifferentiated carcinoma - UCNT / thuộc nhóm Ung thư biểu mô vảy không sừng hóa WHO týp IIb - Type III cũ)",
