      "hint": "Gợi ý: Tại Việt Nam, thể Ung thư biểu mô không biệt hóa của vòm mũi họng (UCNT - liên quan chặt chẽ với EBV) chiếm tới 85–90% tổng số ca K vòm; theo phân loại WHO gộp thì UCNT nằm trong nhóm 'Biểu mô vảy không sừng hóa'.",
      "exp": "Theo Giáo trình Ung thư học Đại học Y Hà Nội: Phân loại mô bệnh học Ung thư biểu mô vòm mũi họng của WHO gồm: (1) Ung thư biểu mô vảy sừng hóa (WHO týp 1: < 5%); (2) Ung thư biểu mô vảy không sừng hóa (Non-keratinizing carcinoma - WHO týp 2), được chia thành thể biệt hóa và thể KHÔNG BIỆT HÓA (Undifferentiated carcinoma of nasopharyngeal type - UCNT, trước đây gọi là WHO týp 3). Tại Việt Nam và Nam Trung Quốc, thể Ung thư biểu mô không biệt hóa (UCNT) chiếm tỷ lệ áp đảo (khoảng 85–90%), liên quan chặt với nhiễm EBV và rất nhạy cảm với tia xạ cũng như hóa chất. Lưu ý khi đi thi: trong đề K118 37HMU (tr.24 Câu 2), đáp án chuẩn được chọn là 'C. Ung thư biểu mô không biệt hóa' (còn ở tr.4 viết tay lưu ý thêm mối liên hệ với nhóm biểu mô vảy không sừng hóa).",
