      "q": "Câu 22 (S3.7 K118 Câu 25 & tr.6 Câu 12 & tr.25 Câu 15). Bệnh nhân có triệu chứng đau quặn bụng từng cơn kèm chướng bụng khu trú, bí trung tiện tạm thời, sau đó sôi bụng và khi trung tiện hoặc đại tiện được thì hết đau hoàn toàn, triệu chứng tái đi tái lại nhiều lần. Đây là hội chứng gì (gợi ý u đại tràng bán tắc)?",
