      "exp": "Theo Giáo trình Ung thư học ĐHYHN: Chẩn đoán giai đoạn ung thư có 5 mục đích và ý nghĩa lớn: (1) Giúp bác sĩ lập kế hoạch điều trị phù hợp nhất cho từng giai đoạn; (2) Đưa ra tiên lượng sống thêm cho người bệnh; (3) Giúp đánh giá khách quan kết quả điều trị; (4) Thuận lợi cho việc trao đổi thông tin giữa các trung tâm điều trị; và (5) Phục vụ công tác nghiên cứu khoa học, thống kê dịch tễ học và kiểm soát ung thư.",
      "ref_label": "Giáo trình Ung thư học Đại học Y Hà Nội & Phân loại AJCC 8th Edition"
