      "exp": "Theo Giáo trình Ung thư học Đại học Y Hà Nội: Đối với đại đa số các bệnh ung thư đặc ở người, nguy cơ tái phát tại chỗ hoặc di căn xa tập trung chủ yếu trong 2–3 năm đầu và giảm rất thấp sau 5 năm. Vì vậy, y văn và thực hành ung thư học lấy mốc thời gian 5 NĂM không tái phát bệnh sau điều trị triệt căn (5-year disease-free survival) để đánh giá là khỏi bệnh trên lâm sàng.",
