      "q": "Câu 25 (S3.7 K118 Câu 23 & tr.6 Câu 19 & tr.24 Câu 5). Câu hỏi về các bệnh ung thư có xét nghiệm sàng lọc trên lâm sàng / cộng đồng (UT đại trực tràng, UT vú, UT cổ tử cung, UT tuyến tiền liệt):",
