      "hint": "Gợi ý: Trong các ung thư phổ biến, PSA là dấu ấn ung thư duy nhất trong máu được ứng dụng sàng lọc trên lâm sàng cho UT tuyến tiền liệt; tuy nhiên xét về sàng lọc diện rộng toàn dân giảm tử vong thì chỉ có K CTC, K vú và K đại trực tràng.",
      "exp": "Phân tích kỹ để bạn xử lý chính xác mọi biến thể của câu hỏi này trong đề thi máy tính Bộ môn Ung thư ĐHYHN: (1) Trong cả 3 bản đề review K118 (tr.3 Câu 23, tr.6 Câu 19, tr.24 Câu 5), các nhóm sinh viên đạt điểm cao đều ghi nhận đáp án chấm điểm là 'Ung thư tuyến tiền liệt' (do trong bài giảng Dấu ấn sinh học ung thư & Sàng lọc: PSA là xét nghiệm máu duy nhất có giá trị sàng lọc phát hiện sớm K tuyến tiền liệt trên lâm sàng, hoặc trong câu hỏi phủ định 'Ung thư nào KHÔNG sàng lọc diện rộng đại trà'); (2) Tuy nhiên về mặt học thuật chuẩn của bài Sàng lọc ung thư: 3 bệnh ung thư có chương trình sàng lọc diện rộng chứng minh giảm tỷ lệ tử vong là Ung thư vú (Mammography), Ung thư cổ tử cung (Pap/HPV) và Ung thư đại trực tràng (FOBT/Nội soi).",
