      "q": "Câu 26 (Review tr.12 Câu 32 & tr.22 Câu 23 & K117 tr.30 Câu 18). Biện pháp nào sau đây là KHÔNG ĐÚNG (TRỪ) trong dự phòng và sàng lọc phát hiện sớm bệnh Ung thư phổi?",
