      "exp": "Theo Quyết định 4825/QĐ-BYT của Bộ Y tế và khuyến cáo quốc tế (NCCN, USPSTF): Xét nghiệm chuẩn dùng để sàng lọc phát hiện sớm ung thư phổi ở nhóm nguy cơ cao (tuổi 50–80, tiền sử hút thuốc lá ≥ 20–30 bao-năm) là Chụp cắt lớp vi tính lồng ngực liều thấp (Low-dose CT - LDCT). Chụp PET/CT hoàn toàn KHÔNG dùng để sàng lọc ung thư phổi mà chỉ dùng để đánh giá giai đoạn (TNM), phát hiện di căn xa và đánh giá đáp ứng điều trị.",
