      "q": "Câu 28 (S3.7 K118 Câu 7 & tr.11 Câu 24 & tr.21 Câu 15 & K117 Câu 14). Phẫu thuật nào sau đây KHÔNG PHẢI là phẫu thuật dự phòng ung thư?",
