      "exp": "Theo Giáo trình Ung thư học ĐHYHN (Bài Phẫu thuật điều trị ung thư): Phẫu thuật dự phòng ung thư gồm: (1) Cắt bao quy đầu ở trẻ hẹp bao quy đầu để dự phòng K dương vật; (2) Hạ tinh hoàn ẩn xuống bìu để dự phòng K tinh hoàn; (3) Khoét chóp cổ tử cung khi có tổn thương loạn sản nặng/tiền ung thư (CIN 2-3/HSIL) dự phòng K cổ tử cung xâm nhập; (4) Cắt đại tràng dự phòng ở bệnh nhân đa polyp gia đình (FAP); (5) Cắt tuyến vú / buồng trứng dự phòng ở người mang đột biến gen BRCA1, BRCA2. Ngược lại, mổ cắt dạ dày/khâu lỗ thủng do thủng ổ loét dạ dày - tá tràng là phẫu thuật điều trị cấp cứu ngoại khoa lành tính, không phải phẫu thuật dự phòng ung thư.",
