      "q": "Câu 30 (S3.7 K118 Câu 15 & tr.6 Câu 10 & tr.24 Câu 6). Trường hợp nào sau đây KHÔNG PHẢI là chỉ định của Phẫu thuật triệt căn trong điều trị ung thư?",
