      "exp": "Theo Giáo trình Ung thư học ĐHYHN (Bài Phẫu thuật điều trị ung thư): (1) Phẫu thuật triệt căn được chỉ định khi u ở giai đoạn sớm tại chỗ - tại vùng, hoặc trường hợp đặc biệt khi có ổ di căn đơn độc ở gan/phổi (ví dụ K đại trực tràng di căn 1 nhân đơn độc ở gan có thể cắt bỏ hoàn toàn cả u nguyên phát và nhân di căn gan đem lại cơ hội khỏi bệnh — phương án B ở tr.2 là ĐÚNG thuộc phẫu thuật triệt căn); (2) Trong đề S3.7 K118 (tr.2 Câu 15 & tr.24 Câu 6), đáp án KHÔNG phải phẫu thuật triệt căn là 'D. Ung thư hắc tố di căn hạch bẹn' (hoặc ở đề tr.6 Câu 10 là 'Phẫu thuật cắt khối u phổi có di căn hạch thượng đòn'). Lưu ý thêm về mặt học thuật: với Ung thư cổ tử cung giai đoạn IIB (xâm lấn parametrium), phác đồ chuẩn hiện nay là Hóa xạ trị đồng thời triệt căn chứ không ưu tiên phẫu thuật Wertheim-Meigs, và phẫu thuật cắt dạ dày khi u đã biến chứng hẹp hang-môn vị không lấy hết u là phẫu thuật giảm nhẹ/tạm thời ('cắt dạ dày sạch sẽ'). Tuy nhiên trong bộ đề trắc nghiệm K118 (tr.2 & tr.24), đáp án chấm điểm là 'D. Ung thư hắc tố di căn hạch bẹn'.",
      "ref_label": "Giáo trình Ung thư học Đại học Y Hà Nội & Phân loại AJCC 8th Edition",
      "is_trap": true,
      "trap_note": "Chú ý 2 biến thể câu 'Phẫu thuật triệt căn KHÔNG áp dụng ở trường hợp nào (PT triệt căn, trừ)?': (1) Biến thể Đề K118 / K120 Lần 2 Câu 16 (tr.20 RV): Giữa K CTC IIB, K gan ổ di căn đơn độc, K phổi di căn hạch thượng đòn (N3), K dạ dày có hẹp môn vị → Chọn 'K phổi di căn hạch thượng đòn (N3)' (vì hạch thượng đòn N3 thuộc giai đoạn IIIB/IIIC chống chỉ định phẫu thuật triệt căn!); (2) Biến thể tr.1–2 RV: Giữa K CTC IIB, K gan di căn ổ đơn độc, K dạ dày hẹp môn vị, K hắc tố di căn hạch bẹn → Lưu ý K hắc tố di căn hạch vùng (hạch bẹn cùng bên chưa di căn xa) vẫn có chỉ định cắt rộng u + vét hạch bẹn triệt căn, còn K CTC giai đoạn IIB điều trị chuẩn bằng Hóa xạ trị đồng thời (không phẫu thuật triệt căn) và nối vị tràng là phẫu thuật tạm thời."
