      "exp": "Theo bài giảng Xạ trị ung thư ĐHYHN: (1) Tổng liều xạ trị phụ thuộc vào độ nhạy cảm tia xạ của từng loại mô bệnh học khối u, kích thước u/giai đoạn bệnh và khả năng chịu đựng (liều dung nạp) của các cơ quan lành lân cận trong vùng chiếu; (2) Phân liều kinh điển thường dùng là 2 Gy/ngày × 5 ngày/tuần (nghỉ thứ 7, Chủ nhật) trong 5–7 tuần chứ không phải chiếu liều cao trong 1–2 ngày đầu; (3) Ngay ở liều thấp (< 50 Gy) tia xạ đã có thể gây biến chứng trên các cơ quan nhạy cảm (như thủy tinh thể mắt gây đục thủy tinh thể từ 2–10 Gy, tinh hoàn/buồng trứng vô sinh từ 2–6 Gy, tủy xương, thận, phổi ~20 Gy).",
