      "q": "Câu 38 (S3.7 K118 Câu 17 & tr.7 Câu 26 & tr.24 Câu 7). Trong các loại khối u ác tính dưới đây, khối u nào ÍT NHẠY CẢM (kháng xạ) nhất với điều trị tia xạ?",
