      "exp": "Đối chiếu trực tiếp với Slide bài giảng Xạ trị của Bộ môn Ung thư ĐHYHN (được đính kèm ở trang 7 của tài liệu PDF): Độ nhạy cảm của khối u với tia xạ được chia làm các mức: (1) Rất nhạy cảm / Nhạy cảm cao (liều diệt u 25–45 Gy): U lympho Hodgkin và không Hodgkin, bệnh bạch cầu, U tinh bào tinh hoàn (Seminoma), U nguyên bào thận (Wilms), U nguyên bào thần kinh; (2) Nhạy cảm vừa (liều diệt u 50–70 Gy): Ung thư biểu mô vảy (ung thư vòm mũi họng, hạ họng, thanh quản, cổ tử cung) và ung thư biểu mô tuyến (ung thư vú, trực tràng); (3) Ít nhạy cảm / Kháng xạ (cần > 70 Gy, vượt quá ngưỡng chịu đựng của mô lành): Ung thư tế bào hắc tố da (Melanoma), Sarcoma xương và Sarcoma phần mềm. Vì vậy: khi đề có 'Ung thư hắc tố da' (tr.2 Câu 17 & tr.24 Câu 7) thì chọn ngay Ung thư hắc tố da; còn khi đề cho 4 lựa chọn 'U lympho, U vòm, U tinh hoàn, U vú' (tr.7 Câu 26) thì U vú (ung thư biểu mô tuyến) ít nhạy xạ hơn so với U lympho, U tinh hoàn và U vòm họng.",
