      "q": "Câu 39 (S3.7 K118 Câu 9 & tr.5 Câu 1 & tr.10–11 Câu 20 & tr.22 Câu 20 & K117 Câu 17). Phát biểu nào sau đây là ĐÚNG về cơ chế tác dụng và đặc điểm của thuốc hóa chất (Chemotherapy) trong điều trị ung thư?",
