      "exp": "Theo Giáo trình Ung thư học Đại học Y Hà Nội (Mục 1.1 Phân loại các nhóm thuốc hóa chất): Các thuốc hóa trị kinh điển là các tác nhân gây độc tế bào (cytotoxic agents) thông qua việc: (1) Tác động trực tiếp lên phân tử ADN (gây đứt gãy chuỗi ADN, tạo liên kết chéo hoặc ức chế tổng hợp purin/pyrimidin) và lên thoi vô sắc (nhóm Taxane, Vinca alkaloid ức chế vi ống làm ngừng phân bào ở pha M); (2) Tác động lên các pha của chu kỳ tế bào làm ngừng chu kỳ tế bào; (3) Kích hoạt con đường chết tế bào theo chương trình (Apoptosis). Vì vậy đáp án chuẩn là 'D. Tất cả các đáp án trên đều đúng'.",
