      "q": "Câu 40 (S3.7 K118 Câu 22 & tr.25 Câu 14). Trong phân loại mức độ nhạy cảm của các bệnh ung thư đối với điều trị hóa chất, nhóm khối u 'Rất nhạy cảm với hóa chất' được định nghĩa là:",
