      "exp": "Theo Giáo trình Ung thư học ĐHYHN (Bảng phân loại mức độ nhạy cảm hóa chất, trang 3 PDF): Các bệnh ung thư được chia thành 4 mức độ nhạy cảm với hóa trị: (1) Rất nhạy cảm — Có thể điều trị khỏi (khối u biến mất hoàn toàn sau hóa trị và có thể khỏi bệnh, gồm: Ung thư nguyên bào nuôi/Choriocarcinoma, Ung thư tế bào mầm tinh hoàn/buồng trứng, Bệnh bạch cầu cấp, U lympho Hodgkin và một số thể không Hodgkin độ ác tính cao, U nguyên bào thận Wilms, U nguyên bào thần kinh); (2) Nhạy cảm nhưng hiếm khi điều trị khỏi bằng hóa chất đơn thuần (K vú, K buồng trứng, K đại trực tràng, K phổi tế bào nhỏ); (3) Ít nhạy cảm hơn (K dạ dày, K phổi không tế bào nhỏ, K đầu cổ, K bàng quang); (4) Kháng hóa chất (K tụy, K thận, Ung thư hắc tố).",
