      "exp": "Theo Giáo trình Ung thư học ĐHYHN: Điều trị tân bổ trợ (Neoadjuvant therapy — còn gọi là điều trị bổ trợ trước) là phương pháp điều trị toàn thân (hóa chất, đích, miễn dịch, nội tiết) hoặc xạ trị được thực hiện TRƯỚC phương pháp điều trị triệt căn tại chỗ - tại vùng (phẫu thuật). Vai trò của điều trị bổ trợ trước gồm cả 3 ý A, B và C: giảm kích thước u và giảm giai đoạn giúp chuyển u từ không mổ được thành mổ được (hoặc từ cắt toàn bộ sang phẫu thuật bảo tồn), đánh giá trực tiếp độ nhạy cảm của u với phác đồ hóa chất trên bệnh phẩm mổ (đáp ứng hoàn toàn về mô bệnh học - pCR), và khống chế sớm các ổ vi di căn.",
      "ref_label": "Giáo trình Ung thư học Đại học Y Hà Nội & Phân loại AJCC 8th Edition"
