      "q": "Câu 42 (Đề 30' tr.6 Câu 11 & tr.17 Câu 5 & tr.21 Câu 17). Bệnh nhân nữ 45 tuổi được chẩn đoán ung thư vú giai đoạn cT2N0M0, đã được phẫu thuật triệt căn cắt tuyến vú và vét hạch nách. Sau khi phẫu thuật, bệnh nhân được chỉ định điều trị hóa chất. Mục đích / tên gọi của hóa trị ở bệnh nhân này là:",
