      "exp": "Theo Quyết định 3128/QĐ-BYT của Bộ Y tế và Giáo trình Ung thư học ĐHYHN: Hóa trị được thực hiện SAU khi đã phẫu thuật lấy bỏ khối u nguyên phát và vét hạch vùng (khi trên lâm sàng và chẩn đoán hình ảnh không còn thấy tổn thương đại thể) được gọi là Hóa trị bổ trợ (Adjuvant chemotherapy). Mục đích của điều trị bổ trợ là tiêu diệt các ổ tế bào ung thư vi thể (micrometastases) có thể còn sót lại tại chỗ hoặc trong tuần hoàn, từ đó làm giảm tỷ lệ tái phát và kéo dài thời gian sống thêm toàn bộ.",
