      "ref_url": "https://thuvienphapluat.vn/van-ban/The-thao-Y-te/Quyet-dinh-3128-QD-BYT-2020-Huong-dan-chan-doan-va-dieu-tri-ung-thu-vu-447926.aspx",
      "stem_id": "case_onco_vu_t2n0_adj"
