      "q": "Câu 43 (Review tr.10 Câu 19 & tr.20 Câu 7 & K117 tr.30 Câu 16). Phát biểu nào sau đây là ĐÚNG về Liệu pháp miễn dịch (Immunotherapy) trong điều trị ung thư?",
