        "A. Bao gồm các thuốc ức chế điểm kiểm soát miễn dịch (như kháng thể đơn dòng ức chế PD-1, PD-L1, CTLA-4, LAG-3), liệu pháp tế bào lympho T (CAR-T, TILs) và vắc-xin điều trị ung thư",
