      "exp": "Theo Giáo trình Ung thư học ĐHYHN: Liệu pháp miễn dịch điều trị ung thư là phương pháp điều trị sinh học toàn thân nhằm kích thích hoặc khôi phục khả năng của hệ thống miễn dịch tự nhiên (đặc biệt là tế bào lympho T CD8+) để nhận diện và tiêu diệt tế bào ung thư. Các phương pháp miễn dịch chính bao gồm: các chất ức chế điểm kiểm soát miễn dịch (Immune checkpoint inhibitors: kháng PD-1 như Pembrolizumab, Nivolumab; kháng PD-L1 như Atezolizumab, Durvalumab; kháng CTLA-4 như Ipilimumab; kháng LAG-3 như Relatlimab), liệu pháp tế bào T chuyển gen (CAR-T), cytokine và vắc-xin trị liệu ung thư.",
