      "hint": "Gợi ý: Trong 5 nguyên tắc điều trị bệnh ung thư của ĐHYHN: theo dõi sát đáp ứng và xử trí/dự phòng độc tính (nôn, hạ bạch cầu...) là nguyên tắc đảm bảo an toàn và duy trì liều điều trị.",
