      "exp": "Theo Bảng quy đổi liều giảm đau tương đương của Bộ Y tế (Quyết định 183/QĐ-BYT) và Giáo trình ĐHYHN (trang 3 PDF): Do Morphin đường uống chịu hiệu ứng chuyển hóa bước đầu qua gan (first-pass metabolism) rất lớn làm sinh khả dụng đường uống chỉ đạt khoảng 30–35%, nên liều Morphin đường uống phải gấp 3 LẦN liều Morphin đường tiêm (tĩnh mạch hoặc dưới da): Morphin uống 30 mg = Morphin tiêm 10 mg.",
