      "q": "Câu 59 (S3.7 K118 Câu 24 & tr.5 Câu 3 & tr.25 Câu 12). Sau khi được chuyển hóa tại gan, Morphin (và các chất chuyển hóa có hoạt tính như M6G, M3G) được đào thải chủ yếu ra khỏi cơ thể qua cơ quan nào?",
