      "q": "Câu 67 (Case 1 K vú T2N1M0 - Câu 1/2 - tr.3, tr.13, tr.21, tr.26, tr.31). Bệnh nhân nữ 51 tuổi, được chẩn đoán xác định Ung thư vú giai đoạn cT2N1M0. Sau khi hội chẩn tiểu ban đa chuyên khoa (hội chẩn toàn ban), các bác sĩ thống nhất quyết định bệnh nhân cần điều trị hóa chất tân bổ trợ trước bằng phác đồ TC rồi mới phẫu thuật. Việc hội chẩn và thống nhất phác đồ trước khi bắt đầu điều trị này thể hiện nguyên tắc nào trong điều trị ung thư?",
