      "exp": "Theo Giáo trình Ung thư học Đại học Y Hà Nội (Bài Đại cương các phương pháp điều trị ung thư): 5 nguyên tắc cơ bản trong điều trị ung thư gồm: (1) Phải có chẩn đoán xác định mô bệnh học và giai đoạn TNM trước điều trị; (2) Xác định rõ mục đích điều trị (triệt căn hay tạm thời); (3) LẬP KẾ HOẠCH ĐIỀU TRỊ (phối hợp đa chuyên khoa hội chẩn để vạch ra trình tự và phác đồ điều trị cụ thể trước khi bắt đầu can thiệp đầu tiên); (4) Bổ sung / điều chỉnh kế hoạch điều trị trong quá trình điều trị dựa trên đáp ứng và diễn biến thực tế; (5) Theo dõi sát và xử trí biến chứng / theo dõi định kỳ sau điều trị. Do đó việc hội chẩn toàn ban đưa ra quyết định hóa trị tân bổ trợ phác đồ TC là 'Nguyên tắc lập kế hoạch điều trị'.",
