      "q": "Câu 68 (Case 1 K vú T2N1M0 - Câu 2/2 - tr.3, tr.23, tr.26, tr.31). Bệnh nhân nữ 51 tuổi (K vú T2N1M0) nêu trên sau khi điều trị hóa chất phác đồ TC được 2 chu kỳ thì xuất hiện biến chứng hạ bạch cầu hạt mức độ nặng (độ 4). Bác sĩ điều trị xử trí và thêm chỉ định dùng thuốc kích thích tăng bạch cầu (G-CSF) dự phòng từ chu kỳ thứ 3 trở đi. Việc làm này thể hiện nguyên tắc nào trong điều trị ung thư?",
