      "q": "Câu 69 (Case 2 K vòm họng hạch 2 bên - Câu 1/3 - tr.3, tr.13, tr.23, tr.34). Bệnh nhân nam 40 tuổi, vào viện vì chảy dịch tai trái, sau đó ù tai, nghe kém tai trái, kèm ngạt tắc mũi trái và khịt khạc dịch nhầy lẫn máu tươi 1 tháng nay. Khám thấy hạch cổ 2 bên nhóm I, II (và/hoặc nhóm III) rắn chắc, kích thước 4 cm, hạch thượng đòn (-). Cận lâm sàng ĐẦU TIÊN cần chỉ định để thăm khám tổn thương nguyên phát ở bệnh nhân này là:",
