      "exp": "Áp dụng chuẩn xác Bảng phân loại TNM Ung thư vòm mũi họng (AJCC 8th Edition & Bài giảng Bộ môn Ung thư ĐHYHN): (1) Đánh giá T (Khối u nguyên phát): U xâm lấn hốc mũi (mức T1), khoang cạnh hầu / cơ chân bướm (mức T2) và xâm lấn XƯƠNG NỀN SỌ (Skull base invasion — tiêu chuẩn định nghĩa của T3; chỉ khi u xâm lấn vào NỘI SỌ hoặc tổn thương dây thần kinh sọ / ổ mắt / hạ họng mới là T4) → Vậy khối u này là T3; (2) Đánh giá N (Hạch vùng): Bệnh nhân có hạch cổ nhóm I, II ở CẢ 2 BÊN (bilateral), kích thước lớn nhất là 4 cm (≤ 6 cm) và nằm trên hố thượng đòn (hạch thượng đòn âm tính) → Vậy hạch vùng là N2 (còn N1 là hạch cổ 1 bên ≤ 6 cm; N3 là hạch > 6 cm hoặc có hạch thượng đòn); (3) Chưa di căn xa là M0. Kết hợp lại, chẩn đoán giai đoạn chính xác tuyệt đối là cT3N2M0 (như đã khoanh đúng ở trang 4 và trang 14).",
