      "q": "Câu 74 (Case Ung thư hắc tố gót chân - Câu 1/4 - tr.4 Case 3 & tr.26 Câu 21). Bệnh nhân nam, cách đây mấy tháng có nốt ruồi nhỏ ở vùng gót chân phải. Dạo gần đây nốt này biến đổi hình dạng bất đối xứng khác so với ban đầu, kích thước to nhanh dần lên, bề mặt có loét và chảy dịch hồng. Khi tiếp cận thăm khám lâm sàng cho bệnh nhân này, cách khám ĐÚNG là:",
