      "q": "Câu 110 (Review S3.7 K120 Lần 2 - Case K vòm Câu 21–25 - Câu 1/5). Bệnh nhân nam vào viện vì triệu chứng ù tai kéo dài. Nội soi tai mũi họng phát hiện khối u sùi loét, hoại tử đen ở vòm mũi họng và đã sinh thiết chẩn đoán xác định Ung thư vòm mũi họng. Để đánh giá đầy đủ mức độ xâm lấn tại chỗ - tại vùng và tầm soát di căn xa (bilan trước điều trị), bộ cận lâm sàng chuẩn cần đề xuất là:",
