      "exp": "Theo Giáo trình Ung thư học Đại học Y Hà Nội (Bài Đại cương xạ trị ung thư): Xạ trị gồm 3 kỹ thuật chính dựa theo vị trí nguồn xạ: (1) Xạ trị chiếu ngoài (nguồn xạ đặt ngoài cơ thể cách một khoảng cách); (2) Xạ trị áp sát (Brachytherapy: dùng các nguồn phóng xạ KÍN đặt vào trong các hốc tự nhiên như buồng tử cung - âm đạo hoặc cắm trực tiếp vào mô u); (3) XẠ TRỊ TRONG (hay Xạ trị chuyển hóa - Metabolic/Systemic internal radiotherapy): sử dụng các đồng vị phóng xạ NGUỒN HỞ đưa vào cơ thể qua đường uống hoặc tiêm tĩnh mạch, thuốc sẽ tập trung đặc hiệu vào mô đích theo con đường chuyển hóa sinh học để phát tia bức xạ (beta) tiêu diệt tế bào u — điển hình nhất là uống I-131 trong ung thư tuyến giáp thể biệt hóa và P-32, Stronti-89, Samarium-153 trong di căn xương.",
      "ref_label": "Giáo trình Ung thư học Đại học Y Hà Nội & Phân loại AJCC 8th Edition"
