      "exp": "Theo Giáo trình Ung thư học Đại học Y Hà Nội (Bài Quá trình sinh bệnh ung thư - mục Động học sự phát triển khối u): Thời gian nhân đôi thể tích khối u (Doubling time - DT) khác nhau rất rõ rệt giữa các loại mô học: (1) Nhóm nhân đôi cực nhanh (DT cực ngắn, khoảng 1–5 ngày): U lympho Burkitt (DT chỉ khoảng 24–48 giờ), bệnh bạch cầu cấp, ung thư tinh hoàn; (2) Nhóm nhân đôi nhanh trung gian (DT khoảng 30–50 ngày): Ung thư phổi tế bào nhỏ, Sarcoma Ewing; (3) Nhóm nhân đôi chậm (DT dài khoảng 90–150 ngày hoặc hơn): Ung thư biểu mô tuyến đại trực tràng, ung thư phổi không tế bào nhỏ, ung thư vú. Trong đề thi máy tính (khi không có phương án 3-2-1), câu hỏi sắp xếp theo tốc độ nhân đôi giảm dần (từ nhân đôi nhanh nhất đến chậm nhất) nên đáp án chuẩn xác duy nhất là B: (1) → (2) → (3).",
      "ref_label": "Giáo trình Ung thư học Đại học Y Hà Nội & Phân loại AJCC 8th Edition",
      "is_trap": true,
