      "exp": "Theo Handout S3.7 Tập 1 (Bảng các gen kháng ung thư và gen sửa chữa ADN, tr.22–26): (1) Gen APC (Adenomatous Polyposis Coli) nằm trên NHÁNH DÀI nhiễm sắc thể số 5 (5q21), không phải nhánh ngắn (5p) — đây là câu bẫy đổi chữ 'dài' thành 'ngắn' trong đề thi; (2) Gen TP53 nằm ở nhánh ngắn NST 17 (17p), gen RB1 ở nhánh dài NST 13 (13q14), gen DCC ở nhánh dài NST 18 (18q), gen BRCA1 ở NST 17q và BRCA2 ở NST 13q; (3) Các gen sửa chữa bắt cặp sai ADN (hMSH2 ở 2p, hMLH1 ở 3p, hPMS1, hPMS2) khi đột biến gây Hội chứng Lynch (HNPCC).",
