      "exp": "Theo Giáo trình Ung thư học và Nội khoa ĐHYHN: Các yếu tố nguy cơ chính của Ung thư đại trực tràng gồm: (1) Dinh dưỡng: ăn nhiều mỡ động vật, thịt đỏ chế biến sẵn, ít chất xơ, thiếu vitamin A, C, E, calci; (2) Các tổn thương tiền ung thư và viêm mạn tính thực thể (IBD): Polyp tuyến đại trực tràng (u tuyến ống, tuyến nhánh), Bệnh đa polyp tuyến gia đình (FAP - nguy cơ ung thư hóa gần 100% nếu không cắt đại tràng dự phòng), Viêm loét đại trực tràng chảy máu và bệnh Crohn; (3) Di truyền: Hội chứng Lynch (HNPCC). Ngược lại, Hội chứng ruột kích thích (IBS) chỉ là rối loạn chức năng vận động ống tiêu hóa, không gây tổn thương thực thể niêm mạc và KHÔNG làm tăng nguy cơ ung thư đại trực tràng.",
      "ref_label": "Giáo trình Ung thư học Đại học Y Hà Nội (Handout Module S3.7 Tập 1 & Tập 2) & Hướng dẫn Bộ Y tế",
