      "q": "Câu 145 (Đề cương S3.7 - Câu 5.1). Trong 3 cấp độ (3 bước) dự phòng bệnh ung thư, bước dự phòng nào là TÍCH CỰC NHẤT và QUAN TRỌNG NHẤT nhằm làm giảm tỷ lệ mới mắc (Incidence) ung thư trong cộng đồng?",
