      "exp": "Theo Handout S3.7 Tập 1 (Bài Dự phòng ung thư, tr.43–45):\n• Dự phòng bước 1 (Primary prevention): Là phòng ngừa ban đầu bằng cách loại bỏ hoặc giảm tối đa sự tiếp xúc với các chất gây ung thư (không hút thuốc lá, hạn chế rượu bia, dinh dưỡng hợp lý, bảo hộ lao động, tiêm vắc-xin phòng HBV và HPV). Đây là bước dự phòng TÍCH CỰC NHẤT và CƠ BẢN NHẤT làm giảm tỷ lệ mới mắc ung thư.\n• Dự phòng bước 2 (Secondary prevention): Là sàng lọc (screening) phát hiện sớm tổn thương tiền ung thư hoặc ung thư giai đoạn rất sớm khi chưa có triệu chứng lâm sàng ở quần thể khỏe mạnh/nguy cơ cao, giúp điều trị khỏi và giảm tỷ lệ tử vong.\n• Dự phòng bước 3 (Tertiary prevention): Thăm khám định kỳ phát hiện tái phát, điều trị và phục hồi chức năng sau khi bệnh đã biểu hiện.",
      "ref_label": "Giáo trình Ung thư học Đại học Y Hà Nội (Handout Module S3.7 Tập 1 & Tập 2) & Hướng dẫn Bộ Y tế"
