      "q": "Câu 146 (Đề cương S3.7 - Câu 5.2). Một chương trình và xét nghiệm sàng lọc (Screening test) bệnh ung thư có hiệu quả cần thỏa mãn các tiêu chuẩn của WHO sau đây, NGOẠI TRỪ:",
