      "exp": "Theo Handout S3.7 Tập 1 (tr.46–48): Tiêu chuẩn để tổ chức sàng lọc một bệnh ung thư gồm: (1) Bệnh phổ biến, gây gánh nặng tử vong lớn; (2) Hiểu rõ lịch sử tự nhiên của bệnh, có giai đoạn tiền ung thư hoặc tiền lâm sàng kéo dài; (3) Có phương pháp điều trị hiệu quả cao ở giai đoạn sớm giúp giảm tỷ lệ tử vong; (4) Test sàng lọc có độ nhạy cao, độ đặc hiệu cao, rẻ tiền, an toàn, dễ áp dụng rộng rãi. Việc 'phải biết thật chính xác nguyên nhân gây bệnh' KHÔNG phải là điều kiện bắt buộc của sàng lọc (ví dụ: ung thư vú hoặc ung thư đại trực tràng đa yếu tố nhưng chương trình sàng lọc bằng X-quang tuyến vú và FOBT/nội soi đại tràng rất thành công).",
      "ref_label": "Giáo trình Ung thư học Đại học Y Hà Nội (Handout Module S3.7 Tập 1 & Tập 2) & Hướng dẫn Bộ Y tế"
