      "q": "Câu 147 (Đề cương S3.7 - Câu 5.5a & 5.5b). Về dự phòng và sàng lọc phát hiện sớm Ung thư biểu mô tế bào gan (HCC) theo Hướng dẫn của Bộ Y tế và ĐHYHN: (1) Phương pháp chuẩn để sàng lọc phát hiện sớm (Dự phòng bước 2) HCC trên nhóm đối tượng nguy cơ cao (viêm gan virus B, C mạn tính, xơ gan) là gì? (2) Biện pháp nào KHÔNG phải là dự phòng ung thư gan?",
