      "hint": "Gợi ý: Thời gian nhân đôi trung bình của khối HCC là khoảng 4–6 tháng, do đó phác đồ sàng lọc (dự phòng cấp 2) chuẩn quốc tế và Bộ Y tế cho người nhiễm HBV, HCV mạn tính hoặc xơ gan là Siêu âm ổ bụng + Định lượng AFP mỗi 6 tháng/lần.",
