      "exp": "Theo Handout S3.7 Tập 1 (Bài Chẩn đoán ung thư, tr.52–55): Các triệu chứng lâm sàng của ung thư gồm: (1) Dấu hiệu tại chỗ của khối u (sờ thấy u, vết loét không liền, chảy máu bất thường như ho ra máu, đái máu, ỉa máu, ra máu âm đạo, tắc nghẽn cơ quan) — rất thường gặp và nằm trong 7 triệu chứng báo hiệu ung thư; (2) Triệu chứng toàn thân và di căn; (3) HỘI CHỨNG CẬN U (Paraneoplastic syndromes — các rối loạn nội tiết, thần kinh - cơ, huyết học, da khớp do các chất tiết giống hormon hoặc phản ứng tự miễn của khối u gây ra ở vị trí xa khối u mà không phải do di căn trực tiếp): đây là nhóm triệu chứng ÍT GẶP NHẤT trên lâm sàng (chỉ xuất hiện ở khoảng < 8–10% bệnh nhân ung thư, hay gặp nhất ở K phổi tế bào nhỏ, K thận, u tuyến ức).",
