      "q": "Câu 149 (Đề cương S3.7 - Câu 6.2). Kỹ thuật nào sau đây KHÔNG PHẢI là phương pháp lấy bệnh phẩm để chẩn đoán MÔ BỆNH HỌC (Giải phẫu bệnh mô học - Histopathology)?",
