      "exp": "Theo Handout S3.7 Tập 1 (tr.57–59):\n• Xét nghiệm Tế bào học (Cytology) gồm: Chọc hút tế bào bằng kim nhỏ (FNA), tế bào học bong (phiến đồ âm đạo - cổ tử cung Pap smear, tế bào học dịch màng phổi, dịch màng bụng, đờm, nước tiểu). Nhược điểm của FNA là chỉ thấy hình thái tế bào rời, không thấy kiến trúc mô nên không phân biệt được ung thư tại chỗ (CIS) với ung thư xâm nhập.\n• Xét nghiệm Mô bệnh học (Histopathology — TIÊU CHUẨN VÀNG chẩn đoán xác định ung thư) cần lấy được mảnh mô giữ nguyên cấu trúc qua: Sinh thiết kim lõi (Core needle biopsy / Tru-cut), Sinh thiết bấm một phần u, Sinh thiết cắt trọn u, hoặc Sinh thiết tức thì (cắt lạnh trong mổ).\nDo đó, FNA KHÔNG phải là phương pháp lấy bệnh phẩm chẩn đoán mô bệnh học.",
