      "exp": "Theo Handout S3.7 Tập 1 ĐHYHN (Mục Theo dõi sau điều trị, tr.62): Khoảng 80–85% các trường hợp tái phát ung thư xảy ra trong vòng 2–3 năm đầu sau điều trị triệt căn. Do đó phác đồ lịch tái khám chuẩn được chia theo 3 giai đoạn:\n• Trong 2 năm đầu (hoặc 3 năm đầu): Tái khám dày mỗi 2 – 3 tháng / lần.\n• Từ năm thứ 3 đến hết năm thứ 5 (như tình huống bệnh nhân K vú pT2N0M0 đã theo dõi ổn định hết 2 năm đầu): Giãn khoảng cách tái khám thành MỖI 6 THÁNG / LẦN.\n• Sau 5 năm không tái phát (được coi là khỏi bệnh về mặt lâm sàng): Duy trì khám kiểm tra định kỳ MỖI 1 NĂM / LẦN để phát hiện tái phát muộn hoặc ung thư nguyên phát thứ hai.",
