      "q": "Câu 153 (Đề cương S3.7 - Câu 7.5). Một nguyên tắc kỹ thuật bắt buộc trong phẫu thuật ung thư là tránh làm rơi vãi, gieo rắc tế bào ung thư (Tumor seeding) vào vết mổ. Trường hợp nào sau đây KHÔNG PHẢI là ví dụ của ung thư tái phát tại chỗ do rơi vãi tế bào u trong phẫu thuật?",
