      "exp": "Theo Handout S3.7 Tập 1 (Bài Phẫu thuật ung thư - Nguyên tắc vô trùng ung thư học / No-touch isolation technique, tr.72–73): Trong quá trình phẫu thuật, nếu thao tác thô bạo làm vỡ u, không che chắn vết mổ hoặc không thay găng/dụng cụ sau khi chạm vào u, tế bào ung thư có thể rơi vãi và cấy ghép trực tiếp gây tái phát tại: (1) Diện cắt / sẹo mổ; (2) Miệng nối ống tiêu hóa (như miệng nối trực tràng); (3) Lỗ đặt trocar thành bụng/thành ngực trong mổ nội soi (Port-site metastasis). Ngược lại, việc xuất hiện ung thư dạ dày sau khi đã phẫu thuật điều trị ung thư gan là một ung thư nguyên phát thứ hai độc lập, hoàn toàn không phải do rơi vãi tế bào trong mổ.",
