      "q": "Câu 154 (Đề cương S3.7 - Câu 8.2). Khi tia bức xạ ion hóa chiếu vào mô khối u trong xạ trị, cơ chế tác dụng sinh học nào sau đây là QUAN TRỌNG VÀ CHỦ YẾU NHẤT dẫn đến tiêu diệt tế bào ung thư?",
