      "exp": "Theo Handout S3.7 Tập 1 (Bài Đại cương xạ trị ung thư, tr.78–80): Đích sinh học quan trọng nhất của tia bức xạ trong nhân tế bào là phân tử ADN (đặc biệt là đứt gãy chuỗi đôi ADN - Double-strand breaks). Tia xạ gây tổn thương ADN theo 2 cơ chế:\n1. Cơ chế trực tiếp (Direct action - chiếm ~1/3 với tia X/gamma): hạt bức xạ va chạm trực tiếp làm đứt liên kết hóa học trên chuỗi ADN.\n2. Cơ chế GIÁN TIẾP (Indirect action - chiếm ~2/3, là cơ chế CHỦ YẾU NHẤT): Vì nước chiếm ~75–80% khối lượng tế bào, bức xạ ion hóa đánh vào phân tử nước ($H_2O$) tạo ra các gốc tự do ($OH^\\bullet, H^\\bullet, e^-_{aq}$); khi có mặt Oxy ($O_2$), các gốc tự do này tạo thành các gốc peroxyl bền vững phá hủy cấu trúc ADN của tế bào ung thư. Đó cũng là lý do mô u giàu oxy nhạy xạ hơn mô u thiếu oxy (hypoxia).",
      "ref_label": "Giáo trình Ung thư học Đại học Y Hà Nội (Handout Module S3.7 Tập 1 & Tập 2) & Hướng dẫn Bộ Y tế"
