      "exp": "Theo Handout S3.7 Tập 1 (tr.81–83): Mức độ nhạy cảm với tia xạ giảm dần theo thứ tự:\n• Rất nhạy xạ: U lympho ác tính, Bệnh bạch cầu, U tinh (Seminoma), U nguyên bào thần kinh, Ung thư phổi tế bào nhỏ (SCLC).\n• Nhạy xạ mức độ vừa - khá (xạ trị triệt căn tốt ở liều 65–70 Gy): Ung thư biểu mô vảy vùng đầu cổ (vòm mũi họng, thanh quản, khoang miệng), Ung thư biểu mô vảy cổ tử cung, Ung thư vú.\n• Ít nhạy xạ hơn: Ung thư biểu mô tuyến nói chung và Ung thư phổi không tế bào nhỏ (NSCLC).\n• Kháng xạ: Ung thư tế bào hắc tố (Melanoma), Sarcoma xương và phần mềm, U nguyên bào thần kinh đệm (Glioblastoma).\nVì vậy trong tổ hợp 4 đáp án trên, B. Ung thư phổi không tế bào nhỏ là đáp án đúng.",
