      "q": "Câu 161 (Đề cương S3.7 - Câu 10.1a & 10.1b). Theo tài liệu Chăm sóc giảm nhẹ của Bộ Y tế (Quyết định 183/QĐ-BYT) và Handout S3.7 Tập 2 (tr.15): Khái niệm chuẩn của Hiệp hội Nghiên cứu Đau Quốc tế (IASP) định nghĩa ĐAU là gì, và nhận định nào về bản chất của cảm giác đau là ĐÚNG?",
