      "hint": "Gợi ý: Định nghĩa IASP nhấn mạnh đau gồm cả 2 thành tố 'cảm giác' (sensory) và 'cảm xúc' (emotional), có thể do tổn thương thực thể hoặc tiềm tàng; vì vậy đau luôn mang tính CHỦ QUAN của từng cá nhân ( khái niệm 'Đau toàn diện - Total pain' của Cicely Saunders gồm đau thể chất, tâm lý, xã hội và tâm linh).",
      "exp": "Theo Handout S3.7 Tập 2 (tr.15–16) và Quyết định 183/QĐ-BYT năm 2022 của Bộ Y tế: Hiệp hội Nghiên cứu Đau Quốc tế (IASP) định nghĩa: 'Đau là một trải nghiệm khó chịu về mặt cảm giác và cảm xúc, gắn liền với tổn thương mô thực sự hoặc tiềm tàng, hoặc được mô tả giống như có tổn thương đó'. Do có sự tham gia của yếu tố tâm lý, cảm xúc, văn hóa, xã hội và tâm linh (Đau toàn diện - Total Pain), cảm giác đau luôn là TRẢI NGHIỆM CHỦ QUAN và CÁ NHÂN — nghĩa là 'Đau là bất cứ điều gì mà người trải nghiệm nó nói rằng nó đang diễn ra, và tồn tại bất cứ khi nào người bệnh nói rằng nó tồn tại' (McCaffery).",
      "ref_label": "Giáo trình Ung thư học Đại học Y Hà Nội (Handout Module S3.7 Tập 1 & Tập 2) & Hướng dẫn Bộ Y tế"
