      "q": "Câu 162 (Đề cương S3.7 - Câu 10.3a & 10.3b). Khi phân loại đau theo CƠ CHẾ SINH LÝ BỆNH trong ung thư (Handout S3.7 Tập 2 tr.16–17): (1) Có 2 nhóm cơ chế đau thực thể chính là gì (để loại trừ phương án nhiễu trong câu hỏi TRỪ)? (2) Kiểu đau có tính chất 'bỏng rát, tê bì, châm chích như kim châm, giật nhói như điện giật' dọc theo đường đi của dây thần kinh kèm tăng cảm đau (Hyperalgesia) / loạn cảm đau (Allodynia) thuộc cơ chế đau nào?",
