      "ans": "A. Phân loại theo cơ chế sinh lý bệnh gồm Đau cảm thụ (thân thể, tạng) và Đau thần kinh; đau bỏng rát, kim châm, điện giật là ĐAU THẦN KINH",
      "hint": "Gợi ý: Trong đề thi S3.7: Nếu hỏi 'Đâu KHÔNG phải là phân loại đau theo cơ chế sinh lý bệnh?' trong 4 đáp án (Đau thân thể, Đau tạng, Đau thần kinh, Đau tâm thần / Đau cảm giác) thì chọn 'Đau tâm thần' hoặc 'Đau cảm giác'. Nếu mô tả bệnh nhân đau kiểu bỏng rát, tê buốt, kim châm, điện giật (do u chèn ép đám rối thần kinh cánh tay/thắt lưng cùng hoặc sau hóa trị/Zona) thì chọn 'Đau thần kinh' (cần phối hợp thuốc hỗ trợ Gabapentin, Pregabalin, Amitriptylin, Corticoid).",
      "exp": "Theo Handout S3.7 Tập 2 (tr.16–18) và Hướng dẫn Chăm sóc giảm nhẹ Bộ Y tế:\n1. Phân loại đau theo cơ chế sinh lý bệnh gồm 2 nhóm lớn:\n• Đau cảm thụ (Nociceptive pain - do kích thích các thụ thể nhận cảm đau nociceptors còn nguyên vẹn): chia thành Đau thân thể (Somatic pain: da, cơ, xương, khớp — đau khu trú rõ, nhức nhối) và Đau tạng (Visceral pain: các tạng trong ngực, bụng — đau âm ỉ hoặc quặn thắt, mơ hồ, khó định khu, hay kèm buồn nôn, vã mồ hôi).\n• Đau thần kinh (Neuropathic pain - do tổn thương trực tiếp hoặc chèn ép hệ thần kinh ngoại biên hay trung ương): đặc trưng bởi cảm giác ĐAU BỎNG RÁT, TÊ BÌ, CHÂM CHÍCH NHƯ KIM CHÂM, GIẬT NHÓI NHƯ ĐIỆN GIẬT, kèm loạn cảm đau (chạm nhẹ cũng đau - Allodynia).\n2. Các từ như 'Đau cảm giác' hoặc 'Đau tâm thần' trong đề trắc nghiệm là các phương án nhiễu (SAI) khi hỏi về phân loại sinh lý bệnh của đau.",
