      "q": "Câu 163 (Đề cương S3.7 - Câu 10.4). Trong đánh giá và điều trị đau ung thư: Thang điểm đau theo nét mặt Wong-Baker (Wong-Baker FACES Pain Rating Scale) sử dụng bao nhiêu mức độ khuôn mặt biểu cảm, và Thang điều trị đau của Tổ chức Y tế Thế giới (WHO) gồm bao nhiêu bậc?",
