      "exp": "Theo Handout S3.7 Tập 2 (tr.19–21): (1) Thang đánh giá đau theo nét mặt Wong-Baker gồm 6 khuôn mặt vẽ biểu cảm từ mặt cười tươi (0 điểm - không đau) đến mặt khóc dữ dội (10 điểm - đau nặng nhất không thể tưởng tượng được), chia thành 6 mức tương ứng với các điểm 0, 2, 4, 6, 8, 10; (2) Thang điều trị đau của WHO gồm 3 bậc: Bậc 1 (Đau nhẹ 1–3/10: Thuốc không opioid như Paracetamol, NSAIDs ± Thuốc hỗ trợ), Bậc 2 (Đau vừa 4–6/10: Opioid nhẹ như Codein, Tramadol hoặc Morphin liều thấp ± Không opioid ± Thuốc hỗ trợ), Bậc 3 (Đau nặng 7–10/10: Opioid mạnh như Morphin, Oxycodon, Fentanyl, Hydromorphon, Methadon ± Không opioid ± Thuốc hỗ trợ).",
