      "q": "Câu 164 (Đề cương S3.7 - Câu 10.6c - Case Morphin Câu 1/2). Bệnh nhân đau nặng (chưa từng dùng Opioid) được cho uống liều khởi đầu Morphin tác dụng nhanh (5 mg hoặc 10 mg đường uống). Sau 30–60 phút đánh giá lại, nếu bệnh nhân VẪN CÒN ĐAU NẶNG như cũ (mức độ đau không giảm hoặc giảm < 50%), hướng xử trí chuẩn liều (Titration) tiếp theo là gì?",
