      "exp": "Theo Handout S3.7 Tập 2 (Mục Dò liều và điều chỉnh liều Morphin, tr.24–25) và Quyết định 183/QĐ-BYT:\n• Morphin không có liều trần (no ceiling effect), liều đúng là liều khống chế được cơn đau với tác dụng phụ chấp nhận được.\n• Khi bắt đầu dò liều bằng Morphin tác dụng nhanh đường uống (khởi đầu 5–10 mg ở người chưa dùng opioid), cần đánh giá lại hiệu quả giảm đau sau 30 – 60 phút (thời điểm thuốc đạt đỉnh tác dụng đường uống):\n  - Nếu cơn đau vẫn còn ở mức nặng (giảm < 50%): Cho ngay liều tiếp theo với mức liều TĂNG GẤP ĐÔI liều ban đầu (tăng 50–100%).\n  - Nếu cơn đau giảm một phần về mức vừa (giảm ≥ 50% nhưng chưa hết đau): Cho lặp lại liều bằng đúng liều ban đầu.\n  - Nếu đã hết đau hoặc chỉ còn đau nhẹ: Duy trì liều đó định kỳ mỗi 4 giờ.",
