      "q": "Câu 165 (Đề cương S3.7 - Câu 10.6f & Câu 11.4 - Case Morphin Câu 2/2). Khi chỉ định điều trị đau kéo dài bằng Morphin (hoặc các thuốc Opioid khác) cho bệnh nhân ung thư, tác dụng không mong muốn nào sau đây PHỔ BIẾN NHẤT, KHÔNG CÓ HIỆN TƯỢNG DUNG NẠP theo thời gian nên bắt buộc bác sĩ phải kê đơn thuốc dự phòng song song ngay từ ngày đầu tiên, và phác đồ thuốc nhuận tràng dự phòng chuẩn là gì?",
