      "exp": "Theo Handout S3.7 Tập 2 (tr.26 & Bài Chăm sóc giảm nhẹ các triệu chứng khác, tr.33) và Quyết định 183/QĐ-BYT:\n1. Trong các tác dụng phụ của Morphin (táo bón, buồn nôn/nôn, ngủ gà, khô miệng, ngứa, bí tiểu, ức chế hô hấp), TÁO BÓN là tác dụng phụ phổ biến nhất (gặp ở > 90% bệnh nhân) và là tác dụng phụ DUY NHẤT không có hiện tượng dung nạp trong suốt quá trình dùng Opioid. Do đó nguyên tắc bắt buộc: 'Bàn tay kê đơn Opioid phải đồng thời kê đơn thuốc nhuận tràng' (trừ khi bệnh nhân đang tiêu chảy hoặc có tắc ruột cơ học).\n2. Thuốc lựa chọn để dự phòng và điều trị táo bón do Opioid (Câu 11.4): Dùng nhóm nhuận tràng KÍCH THÍCH NHU ĐỘNG RUỘT (Bisacodyl, Senna) đơn thuần hoặc phối hợp với nhóm nhuận tràng THẨM THẤU (Lactulose, Sorbitol, Polyethylene glycol - PEG). Lưu ý: Không dùng nhóm nhuận tràng tạo khối/chất xơ (Psyllium, Methylcellulose) cho bệnh nhân ung thư suy kiệt uống ít nước vì dễ gây kết sỏi phân làm tắc ruột!",
