      "q": "Câu 166 (Đề cương S3.7 - Câu 11.3a - Bẫy 9 - Case Chống nôn Câu 1/3). [Tình huống 1] Một bệnh nhân ung thư chuẩn bị vào truyền hóa chất chu kỳ tiếp theo. Ngay từ khi mới bước vào buồng tiêm truyền hoặc nhìn thấy chai dịch truyền (CHƯA truyền hóa chất vào người), bệnh nhân đã lo âu căng thẳng và xuất hiện buồn nôn, nôn dữ dội (Nôn do tâm lý / Nôn phản xạ có điều kiện trước hóa trị - Anticipatory emesis). Thuốc nào sau đây được lựa chọn ưu tiên theo cơ chế bệnh sinh cho tình huống này?",
