      "q": "Câu 172 (Đề cương S3.7 - Câu 12.4 - Biến thể 3C Đề K115 - Case K vòm K115 Câu 1/2). Bệnh nhân nam 50 tuổi vào viện vì đau nửa đầu phải, ù tai phải và nhìn đôi. Khám lâm sàng thấy mắt phải LÁC TRONG (liệt dây thần kinh sọ số VI), sờ thấy 01 hạch cổ bên phải kích thước 1 cm. Nội soi và chụp MRI vòm thấy khối u vòm xâm lấn hố dưới thái dương và nền sọ, chưa có di căn xa. Chẩn đoán giai đoạn TNM cho bệnh nhân này là gì?",
