      "q": "Câu 175 (Đề cương S3.7 - Câu 13.2a, 13.2b, 13.2c). Theo bảng phân loại TNM Ung thư vú (AJCC 8th Edition & Handout S3.7 Tập 2 tr.49–50), định nghĩa nào sau đây về khối u nguyên phát T4 (T4a, T4b, T4c, T4d) là ĐÚNG?",
