      "q": "Câu 176 (Đề cương S3.7 - Câu 13.4a - Case K vú bảo tồn Câu 1/2). Bệnh nhân nữ đã được phẫu thuật bảo tồn tuyến vú và vét hạch nách. Kết quả giải phẫu bệnh và hóa mô miễn dịch sau mổ: Ung thư biểu mô tuyến vú xâm nhập, diện cắt âm tính, di căn 3/15 hạch nách (pN1a), thụ thể nội tiết ER (+), PR (+), HER2 (-). Phác đồ điều trị bổ trợ tiếp theo sau phẫu thuật cho bệnh nhân này bao gồm:",
