      "exp": "Theo Handout S3.7 Tập 2 (Bài Ung thư vú, tr.52–54) và Quyết định 3128/QĐ-BYT: Lập kế hoạch điều trị bổ trợ sau phẫu thuật bảo tồn trên bệnh nhân này dựa trên 3 trụ cột:\n1. Hóa trị bổ trợ: Vì bệnh nhân đã có di căn 3/15 hạch nách (pN1a), hóa trị toàn thân (phác đồ có Anthracycline và Taxane như AC-T hoặc TC) giúp tiêu diệt vi di căn.\n2. Xạ trị bổ trợ: Là chỉ định BẮT BUỘC sau mọi phẫu thuật bảo tồn tuyến vú (giảm 2/3 nguy cơ tái phát tại chỗ) và càng bắt buộc hơn khi có di căn hạch nách.\n3. Điều trị nội tiết bổ trợ: Vì khối u có ER (+), PR (+), bệnh nhân được chỉ định dùng thuốc nội tiết (Tamoxifen hoặc AI tùy tình trạng mãn kinh) kéo dài 5–10 năm sau khi kết thúc hóa chất.",
