      "q": "Câu 177 (Đề cương S3.7 - Câu 13.4b - Case K vú bảo tồn Câu 2/2). Giả sử trên bệnh nhân ở câu trên (đã phẫu thuật bảo tồn tuyến vú + Hóa trị + Xạ trị + Nội tiết cho K vú ER+, PR+, HER2-), sau 5 năm theo dõi bệnh nhân xuất hiện khối u TÁI PHÁT TẠI CHỖ ngay tại tuyến vú đã bảo tồn (bilan toàn thân chưa phát hiện di căn xa). Hướng xử trí tiếp theo phù hợp nhất là gì?",
      "options": [
        "A. Phẫu thuật cắt toàn bộ tuyến vú cứu vớt (Salvage mastectomy) + Hóa trị / Điều trị toàn thân + Điều trị nội tiết (thay đổi phác đồ nội tiết bậc tiếp theo; lưu ý KHÔNG xạ trị lặp lại liều triệt căn vào thành ngực đã xạ trị đủ liều trước đó)",
        "B. Tiếp tục phẫu thuật bảo tồn lần 2 và chiếu xạ trị liều 70 Gy lặp lại vào đúng vùng vú cũ",
        "C. Không can thiệp phẫu thuật mà chỉ chườm ấm tại chỗ",
        "D. Chỉ tiêm vắc-xin HPV"
      ],
      "correct_idx": 0,
      "ans": "A. Phẫu thuật (cắt tuyến vú cứu vớt) + Hóa trị + Điều trị nội tiết (không xạ trị lại vùng vú đã xạ)",
      "hint": "Gợi ý: Vì bệnh nhân đã từng phẫu thuật bảo tồn và ĐÃ XẠ TRỊ toàn bộ tuyến vú ở lần điều trị đầu, nên khi tái phát tại chỗ tại tuyến vú đó, phương pháp điều trị tại chỗ chuẩn là Phẫu thuật cắt toàn bộ tuyến vú cứu vớt (Salvage mastectomy), kết hợp điều trị toàn thân (Hóa trị + Nội tiết), không chiếu xạ lặp lại!",
      "exp": "Theo Handout S3.7 Tập 2 (tr.54) và Hướng dẫn NCCN / Bộ Y tế: Đối với bệnh nhân ung thư vú tái phát tại chỗ đơn độc tại nhu mô vú sau khi đã điều trị phẫu thuật bảo tồn + xạ trị toàn bộ vú trước đó (Ipsilateral breast tumor recurrence - IBTR):\n• Về điều trị tại chỗ: Do mô vú và thành ngực đã nhận đủ liều xạ trị triệt căn (50 Gy + boost) ở lần điều trị trước nên không còn chỉ định bảo tồn hay xạ trị lại thông thường; phương pháp chuẩn là PHẪU THUẬT CẮT TOÀN BỘ TUYẾN VÚ CỨU VỚT (Salvage total mastectomy).\n• Về điều trị toàn thân sau mổ cứu vớt: Phối hợp Hóa trị (tùy thể trạng và phác đồ trước đó) và đổi sang phác đồ Điều trị nội tiết bậc tiếp theo (do u có ER+, PR+).",
      "ref_label": "Quyết định 3128/QĐ-BYT năm 2020 của Bộ Y tế (Hướng dẫn chẩn đoán và điều trị Ung thư vú)",
