      "q": "Câu 178 (Đề cương S3.7 - Câu 13.5a - Case K vú HER2+++ Câu 1/2). Bệnh nhân nữ đã được phẫu thuật cắt tuyến vú triệt căn và vét hạch nách. Kết quả giải phẫu bệnh sau mổ: Khối u vú kích thước 2 × 3 cm (pT2), độ mô học 3 (Grade 3), di căn 10/12 hạch nách (pN3a), thụ thể nội tiết ER (-), PR (-), bộc lộ quá mức HER2 (+++) trên hóa mô miễn dịch. Các phương pháp điều trị bổ trợ cần chỉ định sau phẫu thuật cho bệnh nhân này là:",
