      "hint": "Gợi ý: Kiểm tra 4 thông số sau mổ của bệnh nhân: (1) U 2×3 cm, độ 3, di căn 10/12 hạch (pN3a) → bắt buộc HÓA TRỊ và XẠ TRỊ thành ngực + hạch thượng/hạ đòn; (2) HER2 (+++) dương tính → bắt buộc ĐIỀU TRỊ ĐÍCH kháng HER2 (Trastuzumab); (3) ER (-), PR (-) → KHÔNG điều trị nội tiết!",
      "exp": "Theo Handout S3.7 Tập 2 (tr.52–54) và Quyết định 3128/QĐ-BYT: Phân tích chỉ định điều trị bổ trợ sau cắt tuyến vú trên bệnh nhân này:\n1. Hóa trị bổ trợ: Khối u pT2, độ mô học 3, di căn tới 10/12 hạch nách (pN3a - nguy cơ tái phát di căn rất cao) → Bắt buộc hóa trị bổ trợ.\n2. Điều trị đích (Targeted therapy): Vì HER2 (+++) dương tính mạnh trên hóa mô miễn dịch (IHC 3+), bắt buộc phối hợp kháng thể đơn dòng kháng HER2 là TRASTUZUMAB (Herceptin, có thể kết hợp Pertuzumab) đủ 1 năm giúp giảm ~50% nguy cơ tái phát.\n3. Xạ trị bổ trợ sau cắt tuyến vú (PMRT): Do có di căn ≥ 4 hạch nách (ở đây là 10/12 hạch - pN3a), bắt buộc xạ trị bổ trợ vào thành ngực và vùng hạch thượng đòn / hạ đòn / vú trong.\n4. Không có chỉ định điều trị nội tiết vì cả ER và PR đều âm tính.",
      "ref_label": "Quyết định 3128/QĐ-BYT năm 2020 của Bộ Y tế (Hướng dẫn chẩn đoán và điều trị Ung thư vú)",
