      "q": "Câu 182 (Đề cương S3.7 - Câu 14.2a & 14.2b). Khi nói về triệu chứng lâm sàng và sàng lọc Ung thư cổ tử cung theo Giáo trình Ung thư học ĐHYHN (Handout Tập 2 tr.58–60): (1) Triệu chứng cơ năng THƯỜNG GẶP NHẤT khiến bệnh nhân K cổ tử cung đi khám là gì? (2) Phương pháp nào sau đây ÍT CÓ GIÁ TRỊ NHẤT trong sàng lọc phát hiện sớm Ung thư cổ tử cung giai đoạn tiền lâm sàng?",
