        "B. (1) Đau thượng vị; (2) Xét nghiệm tế bào học cổ tử cung (Pap smear / ThinPrep)",
        "C. (1) Ho ra máu; (2) Xét nghiệm định týp HPV nguy cơ cao (HPV DNA test)",
        "D. (1) Bí tiểu cấp; (2) Nghiệm pháp chấm Acid acetic / Lugol (VIA / VILI) và Soi cổ tử cung"
