      "ans": "A. Triệu chứng thường gặp nhất: Ra máu âm đạo bất thường; Phương pháp ít giá trị nhất trong sàng lọc giai đoạn sớm: Thăm khám âm đạo bằng tay",
      "hint": "Gợi ý: Ở giai đoạn tiền ung thư (CIN) và K cổ tử cung vi xâm nhập (IA), cổ tử cung nhìn và sờ bằng tay hoàn toàn mềm mại, nhẵn nhụi bình thường. Do đó sàng lọc phát hiện sớm phải dựa vào Tế bào học (Pap test), HPV test, VIA/VILI và Soi cổ tử cung; còn 'Thăm khám âm đạo bằng tay' ít có giá trị nhất trong sàng lọc sớm!",
      "exp": "Theo Handout S3.7 Tập 2 (Bài Ung thư cổ tử cung, tr.58–60) và Quyết định 2402/QĐ-BYT:\n1. Triệu chứng cơ năng thường gặp nhất của K cổ tử cung xâm lấn là RA MÁU ÂM ĐẠO BẤT THƯỜNG (chiếm > 80% các trường hợp có triệu chứng): điển hình là ra máu sau giao hợp (postcoital bleeding), ra máu bất thường ngoài kỳ kinh, rong huyết hoặc ra máu âm đạo ở phụ nữ đã mãn kinh; kèm theo ra dịch âm đạo (khí hư) lẫn máu, mùi hôi.\n2. Về các phương pháp sàng lọc K cổ tử cung giai đoạn sớm: Có 3 nhóm phương pháp sàng lọc chuẩn được Bộ Y tế khuyến cáo là: (a) Xét nghiệm tế bào học cổ tử cung (Pap smear / LBC); (b) Xét nghiệm HPV DNA nguy cơ cao; (c) Quan sát cổ tử cung sau bôi acid acetic 3–5% (VIA) hoặc dung dịch Lugol (VILI). Ngược lại, THĂM KHÁM ÂM ĐẠO BẰNG TAY (TV) không thể nhận biết được các tổn thương loạn sản nội biểu mô (CIN) hay ung thư vi xâm nhập nên ít có giá trị nhất trong sàng lọc giai đoạn sớm.",
