      "exp": "Theo Handout S3.7 Tập 2 (Bài Ung thư cổ tử cung, tr.62–64) và Hướng dẫn Bộ Y tế: Đối với bệnh nhân trẻ mắc K cổ tử cung có mong muốn bảo tồn khả năng sinh sản:\n• Ở giai đoạn IA1 (xâm nhập sâu ≤ 3 mm, không xâm lấn mạch máu - bạch huyết LVSI): Có thể điều trị bằng Khoét chóp cổ tử cung (đảm bảo diện cắt âm tính ≥ 3 mm) và theo dõi sát.\n• Ở giai đoạn IA1 có LVSI (+), IA2 hoặc IB1 (kích thước khối u ≤ 2 cm, chưa di căn hạch): Có thể thực hiện Phẫu thuật cắt cụt cổ tử cung triệt căn (Radical trachelectomy — cắt cổ tử cung, phần trên âm đạo và dây chằng cạnh tử cung nhưng GIỮ LẠI THÂN TỬ CUNG nối với âm đạo) kết hợp vét hạch chậu.\n• Nếu bệnh nhân phải xạ trị tiểu khung: Có thể phẫu thuật treo cao buồng trứng (chuyển vị buồng trứng lên rãnh đại tràng ngoài trường chiếu xạ) và tư vấn hỗ trợ sinh sản (trữ lạnh noãn/phôi).",
