      "q": "Câu 185 (Đề cương S3.7 - Câu 15.1b & 15.1c). Khi nói về đặc điểm lâm sàng và tiên lượng của Ung thư phổi theo Giáo trình Ung thư học ĐHYHN: (1) Ung thư phổi tế bào nhỏ (SCLC) có các đặc điểm tiên lượng xấu sau đây, NGOẠI TRỪ đặc điểm nào? (2) Trên bệnh nhân Ung thư biểu mô vảy ở phổi, sự xuất hiện của triệu chứng cơ năng nào sau đây báo hiệu khối u đã xâm lấn trung thất (giai đoạn T4) nên có TIÊN LƯỢNG XẤU NHẤT?",
