      "hint": "Gợi ý: (1) K phổi tế bào nhỏ (SCLC) tuy rất ác tính, nhân đôi nhanh và di căn sớm nhưng lại RẤT NHẠY với hóa trị và xạ trị (đó là điểm thuận lợi duy nhất, nên là đáp án TRỪ khi hỏi về các đặc điểm xấu của SCLC); (2) Giữa các triệu chứng ho khan, đau ngực, khó thở nhẹ và NÓI KHÀN (giọng đôi), thì Nói khàn chứng tỏ u/hạch đã xâm lấn dây thần kinh quặt ngược trong trung thất (T4), không còn mổ được nên có tiên lượng xấu nhất!",
      "exp": "Theo Giáo trình Ung thư học ĐHYHN và Quyết định 4825/QĐ-BYT (Hướng dẫn chẩn đoán và điều trị Ung thư phổi không tế bào nhỏ):\n1. Về Ung thư phổi tế bào nhỏ (SCLC - chiếm ~15% K phổi): Mang bản chất thần kinh - nội tiết, phân chia cực nhanh, di căn xa rất sớm (não, xương, gan, tuyến thượng thận) và tiên lượng sống thêm 5 năm rất thấp; tuy nhiên khối u lại RẤT NHẠY CẢM với hóa chất và tia xạ ở giai đoạn đầu (do đó khi đề hỏi 'Các đặc điểm tiên lượng xấu của SCLC, TRỪ' thì chọn 'Nhạy với hóa xạ trị').\n2. Về triệu chứng lâm sàng của K phổi: Khi xuất hiện triệu chứng NÓI KHÀN TIẾNG (giọng đôi - bitonal voice) do liệt dây thần kinh thanh quản quặt ngược (đặc biệt bên trái vòng dưới quai động mạch chủ), điều đó chứng tỏ khối u hoặc hạch đã xâm lấn sâu vào trung thất (phân độ T4), bệnh đã ở giai đoạn tiến triển tại vùng không còn khả năng phẫu thuật triệt căn nên mang tiên lượng xấu nhất.",
