      "exp": "Theo Giáo trình Ung thư học ĐHYHN và Quyết định 4825/QĐ-BYT: Để đánh giá đầy đủ sự xâm lấn tại chỗ và tại vùng của Ung thư phổi, cần phối hợp chặt chẽ 2 thăm dò cốt lõi:\n1. Chụp CLVT (CT scan) lồng ngực có tiêm thuốc cản quang: Đánh giá vị trí, kích thước khối u, mức độ xâm lấn màng phổi, thành ngực, trung thất, mạch máu lớn và các nhóm hạch rốn phổi - trung thất.\n2. Nội soi phế quản (Bronchoscopy): Đánh giá trực tiếp tổn thương niêm mạc trong lòng khí - phế quản, xác định khoảng cách từ diện u tới cựa khí quản (Carina) phục vụ lập kế hoạch phẫu thuật, đồng thời bấm sinh thiết làm mô bệnh học (đặc biệt hiệu quả với u phổi trung tâm).",
