      "q": "Câu 187 (Đề cương S3.7 - Câu 15.2b - Case K phổi Câu 2/4). Một bệnh nhân có khối u phổi kích thước 4 cm nằm ở vùng NGOẠI VI phổi (sát thành ngực, xa các phế quản lớn trung tâm). Phương pháp tiếp cận nào sau đây có độ chính xác và khả năng lấy được bệnh phẩm chẩn đoán MÔ BỆNH HỌC cao nhất cho khối u ngoại vi này?",
