      "q": "Câu 188 (Đề cương S3.7 - Câu 15.2c - Case K phổi Câu 3/4). Bệnh nhân được chẩn đoán Ung thư biểu mô tuyến ở thùy giữa phổi phải, kích thước khối u nguyên phát 1,5 cm, đã có di căn hạch trung thất ĐỐI BÊN và/hoặc hạch thượng đòn, chưa phát hiện di căn xa trên PET/CT và MRI sọ não. Chẩn đoán giai đoạn TNM (AJCC 8th) và phác đồ điều trị chuẩn cho bệnh nhân này là gì?",
