      "hint": "Gợi ý: Trong phân loại TNM K phổi (AJCC 8th): U > 1 cm đến ≤ 2 cm là T1b (T1a ≤ 1cm, T1b 1–2cm, T1c 2–3cm). Về hạch N: N1 là hạch quanh phế quản/rốn phổi cùng bên; N2 là hạch trung thất cùng bên và/hoặc hạch dưới carina; N3 là hạch trung thất/rốn phổi ĐỐI BÊN hoặc hạch cơ bậc thang / HẠCH THƯỢNG ĐÒN (bất kể cùng bên hay đối bên). T1bN3M0 thuộc Giai đoạn IIIB (không còn chỉ định phẫu thuật), điều trị chuẩn là Hóa xạ trị đồng thời!",
      "exp": "Theo Phân loại TNM Ung thư phổi AJCC 8th Edition và Quyết định 4825/QĐ-BYT:\n1. Phân độ T: Khối u đường kính lớn nhất ≤ 3 cm thuộc T1, chia làm T1a (≤ 1 cm), T1b (> 1 cm đến ≤ 2 cm — u 1,5 cm của bệnh nhân là T1b), và T1c (> 2 cm đến ≤ 3 cm).\n2. Phân độ N: Hạch rốn phổi/trong phổi cùng bên là N1; Hạch trung thất cùng bên hoặc dưới carina là N2; Hạch trung thất ĐỐI BÊN, hạch rốn phổi đối bên, hoặc hạch cơ bậc thang / HẠCH THƯỢNG ĐÒN (cùng bên hay đối bên) đều xếp là N3.\n3. Giai đoạn và điều trị: Tổ hợp cT1bN3M0 thuộc Giai đoạn IIIB. Vì đã có hạch N3 nên khối u KHÔNG còn chỉ định phẫu thuật (Unresectable stage III NSCLC); phác đồ điều trị tiêu chuẩn là HÓA - XẠ TRỊ ĐỒNG THỜI TRIỆT CĂN (xạ trị 60–66 Gy phối hợp hóa chất bộ đôi có Platin).",
