      "q": "Câu 189 (Đề cương S3.7 - Câu 15.2d - Case K phổi Câu 4/4). Trong điều trị toàn thân cho bệnh nhân Ung thư phổi không tế bào nhỏ (NSCLC) giai đoạn tiến triển / di căn, các nhóm thuốc và liệu pháp nào sau đây ĐƯỢC SỬ DỤNG trên lâm sàng, và phương pháp nào KHÔNG được sử dụng?",
