      "hint": "Gợi ý: Trong đề thi S3.7 có 2 biến thể câu hỏi về điều trị toàn thân K phổi: (1) Nếu hỏi phương pháp KHÔNG dùng trong điều trị toàn thân K phổi → chọn 'Điều trị nội tiết'; (2) Nếu hỏi thuốc đích/kháng thể KHÔNG phải của K phổi → chọn 'Sorafenib' (Sorafenib là thuốc đích của K gan HCC và K thận, K giáp).",
      "exp": "Theo Quyết định 4825/QĐ-BYT và Handout S3.7 Tập 2: Điều trị toàn thân trong Ung thư phổi không tế bào nhỏ (NSCLC) hiện nay bao gồm 4 nhóm vũ khí:\n1. Hóa trị gây độc tế bào (phác đồ bộ đôi có Platin: Cisplatin/Carboplatin kết hợp Pemetrexed, Paclitaxel, Gemcitabine, Vinorelbine).\n2. Thuốc điều trị đích phân tử nhỏ (Targeted TKIs): khi có đột biến gen nhạy thuốc như đột biến EGFR (Gefitinib, Erlotinib, Afatinib, Osimertinib), chuyển đoạn ALK (Crizotinib, Ceritinib, Alectinib), ROS1.\n3. Kháng thể đơn dòng kháng sinh mạch (Anti-VEGF): Bevacizumab phối hợp hóa chất (trong NSCLC không phải tế bào vảy).\n4. Liệu pháp miễn dịch ức chế chốt kiểm soát (Immune checkpoint inhibitors): Pembrolizumab, Nivolumab, Atezolizumab, Durvalumab.\nNgược lại, Ung thư phổi không phụ thuộc hormon sinh dục nên KHÔNG áp dụng Điều trị nội tiết.",
