      "q": "Câu 190 (Đề cương S3.7 - Câu 15.3b & 15.3c). Khi nói về Ung thư đại trực tràng theo Giáo trình Ung thư học ĐHYHN: (1) Phương tiện chẩn đoán hình ảnh nào có giá trị tốt nhất để đánh giá độ sâu xâm lấn thành trực tràng (T) và hạch vùng (N) trong Ung thư trực tràng thấp và trung bình? (2) Yếu tố nào là yếu tố TIÊN LƯỢNG quan trọng nhất sau phẫu thuật K đại trực tràng, và chất dinh dưỡng nào giúp làm GIẢM nguy cơ K đại trực tràng?",
