      "hint": "Gợi ý: Đối với K trực tràng 1/3 giữa và dưới, Siêu âm nội soi (EUS/ERUS - rất nhạy với T1, T2) và MRI tiểu khung độ phân giải cao (đánh giá chính xác T3, T4, cân mạc treo trực tràng MRF và hạch chậu) là 2 phương tiện chuẩn vàng để quyết định Hóa xạ trị tiền phẫu. Về dinh dưỡng: Chất xơ giúp tăng khối lượng phân, rút ngắn thời gian lưu phân và giảm tiếp xúc của niêm mạc đại tràng với các chất sinh ung trong dịch mật.",
      "exp": "Theo Giáo trình Ung thư học ĐHYHN và Quyết định 2549/QĐ-BYT (Hướng dẫn chẩn đoán và điều trị Ung thư đại trực tràng):\n1. Đánh giá giai đoạn tại chỗ - tại vùng trong Ung thư trực tràng: Siêu âm nội soi trực tràng (Endorectal Ultrasound - ERUS) và Chụp cộng hưởng từ (MRI) tiểu khung là 2 phương tiện chuẩn xác nhất để xác định độ sâu xâm lấn qua các lớp thành trực tràng (T), diện cắt chu vi (CRM), cân mạc treo trực tràng và tình trạng di căn hạch vùng (N).\n2. Yếu tố tiên lượng quan trọng nhất của K đại trực tràng sau phẫu thuật triệt căn là Giai đoạn bệnh theo TNM — đặc biệt là độ sâu xâm lấn thành ruột (T) và tình trạng di căn hạch bạch huyết vùng (N).\n3. Về dự phòng dinh dưỡng: Khẩu phần ăn giàu CHẤT XƠ (rau xanh, hoa quả tươi, ngũ cốc nguyên hạt) giúp hòa loãng các tác nhân gây ung thư trong lòng ruột và tăng nhu động ruột đẩy nhanh đào thải phân, từ đó làm giảm nguy cơ mắc K đại trực tràng.",
