      "hint": "Gợi ý: Tổng hợp 4 câu hỏi K dạ dày trong đề thi S3.7: (1) Triệu chứng XHTH do K dạ dày → Đi ngoài phân đen; (2) Đâu KHÔNG phải triệu chứng muộn của K dạ dày → Nóng rát sau xương ức; (3) Đâu KHÔNG thuộc hội chứng hẹp môn vị → Hình thấu kính trên phim Baryt / Tăng tiết nước bọt (hẹp môn vị trên X-quang có hình ảnh tuyết rơi và đáy chậu có 3 mức: dịch vị, baryt, hơi; lâm sàng nôn ra thức ăn cũ bữa trước gây mất nước, lắc óc ách lúc đói); (4) Đánh giá độ sâu xâm lấn thành dạ dày (T1a khu trú niêm mạc) trước khi cắt hớt niêm mạc nội soi (EMR/ESD) → Siêu âm nội soi (EUS).",
      "exp": "Theo Giáo trình Ung thư học ĐHYHN và Quyết định 2742/QĐ-BYT năm 2020 (Hướng dẫn chẩn đoán và điều trị Ung thư dạ dày):\n1. Về triệu chứng lâm sàng: Xuất huyết tiêu hóa mạn tính hoặc cấp tính trong K dạ dày biểu hiện điển hình bằng ĐI NGOÀI PHÂN ĐEN (melena) và nôn ra máu bầm đen; Hội chứng hẹp môn vị (u vùng hang - môn vị) gồm đau thượng vị sau ăn, nôn ra thức ăn cũ của hôm trước có mùi chua nồng, dấu hiệu Bouveret (+), lắc óc ách lúc đói (+), X-quang dạ dày có hình ảnh 'tuyết rơi' và hình đáy chậu rộng có 3 lớp (chứ KHÔNG có hình thấu kính và không gây tăng tiết nước bọt).\n2. Về mô bệnh học (Phân loại Lauren): Típ ruột (thể biệt hóa) có liên quan chặt chẽ với nhiễm Helicobacter pylori mạn tính và tiến triển theo chuỗi Correa (Viêm dạ dày mạn → Viêm dạ dày teo → Dị sản ruột → Loạn sản → Ung thư biểu mô tuyến).\n3. Về chẩn đoán độ sâu xâm lấn (T): SIÊU ÂM NỘI SOI (Endoscopic Ultrasound - EUS) cho phép phân biệt rõ 5 lớp thành dạ dày, là phương tiện tốt nhất để xác định u còn khu trú ở lớp niêm mạc (T1a) chưa di căn hạch nhằm chỉ định Cắt hớt niêm mạc qua nội soi (EMR / ESD).",
