      "q": "Câu 193 (Đề cương S3.7 - Câu 15.4d_2 - Case K dạ dày Câu 2/2). Sau khi sinh thiết lại khẳng định Ung thư biểu mô tuyến dạ dày vùng hang vị, kết quả đánh giá bilan trước mổ xác định giai đoạn cT4aN1M0 (khối u xâm lấn tới thanh mạc dạ dày, di căn 1–2 hạch vùng quanh dạ dày, chưa xâm lấn tạng lân cận, chưa di căn xa, thể trạng tốt). Hướng điều trị chuẩn cho bệnh nhân này là gì?",
