      "q": "Câu 194 (Đề cương S3.7 - Câu 15.5a_1 - Case HCC & K lưỡi Câu 1/3). Một bệnh nhân có tiền sử viêm gan virus B mạn tính, siêu âm và chụp cắt lớp vi tính ổ bụng có tiêm thuốc cản quang phát hiện khối u gan kích thước > 2 cm có tính chất động học điển hình: 'Ngấm thuốc cản quang mạnh ở thì động mạch (Wash-in) và thải thuốc nhanh ở thì tĩnh mạch cửa / thì muộn (Wash-out)'. Xét nghiệm dấu ấn sinh học máu nào cần được chỉ định phối hợp để khẳng định chẩn đoán xác định Ung thư biểu mô tế bào gan (HCC)?",
