      "exp": "Theo Quyết định 3129/QĐ-BYT năm 2020 của Bộ Y tế (Hướng dẫn chẩn đoán và điều trị Ung thư biểu mô tế bào gan - HCC) và Giáo trình Ung thư học ĐHYHN: Khác với hầu hết các loại ung thư khác bắt buộc phải có giải phẫu bệnh, HCC có thể được CHẨN ĐOÁN XÁC ĐỊNH dựa trên tiêu chuẩn không xâm lấn khi phối hợp:\n1. Hình ảnh học điển hình trên CT đa dãy hoặc MRI gan có tiêm thuốc tương phản: Khối u gan có hiện tượng TĂNG SINH MẠCH ĐIỂN HÌNH — ngấm thuốc mạnh ở thì động mạch (Arterial phase hyperenhancement) và thải thuốc nhanh ở thì tĩnh mạch cửa hoặc thì muộn (Portal venous / delayed phase washout).\n2. Xét nghiệm chất chỉ điểm khối u trong máu: Định lượng AFP (Alpha-fetoprotein) huyết thanh (khi AFP ≥ 400 ng/mL, hoặc AFP tăng cao hơn giới hạn bình thường kèm nhiễm HBV/HCV; ngoài ra có thể phối hợp bộ ba AFP, AFP-L3 và PIVKA-II).",
