      "q": "Câu 195 (Đề cương S3.7 - Câu 15.5a_2 - Case HCC & K lưỡi Câu 2/3). Bệnh nhân nam được chẩn đoán xác định Ung thư biểu mô tế bào gan (HCC) kích thước lớn có huyết khối tĩnh mạch cửa, trên nền xơ gan mất bù nặng (phân độ suy gan Child-Pugh C: cổ trướng lượng nhiều, vàng da đậm, bệnh não gan, toàn trạng suy kiệt PS 3–4 — tương ứng giai đoạn BCLC D). Hướng điều trị phù hợp nhất cho bệnh nhân này là gì?",
