      "exp": "Theo Quyết định 3129/QĐ-BYT năm 2020 của Bộ Y tế và Phân loại BCLC (Barcelona Clinic Liver Cancer):\n• Tiên lượng và quyết định điều trị HCC phụ thuộc đồng thời vào 3 yếu tố: (1) Đặc điểm khối u và xâm lấn mạch máu (huyết khối tĩnh mạch cửa), (2) Chức năng gan nền (thang điểm Child-Pugh A, B, C), và (3) Toàn trạng người bệnh (ECOG PS).\n• Khi bệnh nhân đã ở mức suy gan nặng mất bù CHILD-PUGH C kèm huyết khối tĩnh mạch cửa (Giai đoạn cuối - BCLC stage D), các phương pháp can thiệp đặc hiệu như Phẫu thuật cắt gan, Nút mạch hóa chất (TACE) hay Thuốc điều trị đích (Sorafenib/Lenvatinib) đều bị chống chỉ định vì sẽ gây suy gan cấp không hồi phục. Phương pháp điều trị đúng đắn nhất là ĐIỀU TRỊ GIẢM NHẸ TRIỆU CHỨNG (Best Supportive Care).",
      "ref_label": "Quyết định 3129/QĐ-BYT năm 2020 của Bộ Y tế (Hướng dẫn chẩn đoán và điều trị Ung thư biểu mô tế bào gan)",
