      "q": "Câu 196 (Đề cương S3.7 - Câu 15.5b_1, 15.5b_2, 15.5b_3 - Case HCC & K lưỡi Câu 3/3). Khi nói về Ung thư lưỡi (phần lưỡi di động trong khoang miệng) theo Giáo trình Ung thư học ĐHYHN: (1) Thể mô bệnh học chiếm đa số tuyệt đối (> 95%) của ung thư lưỡi là gì? (2) Ung thư bờ bên lưỡi thường di căn bạch huyết sớm nhất đến nhóm hạch cổ nào? (3) Với khối u bờ bên lưỡi kích thước 2 cm, sâu ≤ 5 mm, chưa di căn hạch cổ (cT1N0M0), phương pháp điều trị chuẩn đầu tay là gì?",
