        "C. (1) Mô bệnh học chủ yếu là U nguyên bào thần kinh; (2) Không bao giờ di căn hạch cổ; (3) Chỉ theo dõi không điều trị",
        "D. (1) Mô bệnh học chủ yếu là Ung thư biểu mô tế bào nhẫn; (2) Di căn hạch nách; (3) Điều trị nội tiết bằng Letrozole"
