      "hint": "Gợi ý: Niêm mạc khoang miệng và lưỡi được phủ bởi biểu mô lát tầng không sừng hóa, nên > 95% ung thư lưỡi là Ung thư biểu mô tế bào vảy (liên quan hút thuốc lá, uống rượu, ăn trầu, răng sắc nhọn cọ xát mạn tính). Lưỡi rất giàu mạch bạch huyết và vận động liên tục nên di căn hạch cổ nhóm I (dưới hàm - dưới cằm) và nhóm II (cảnh cao) rất sớm.",
      "exp": "Theo Giáo trình Ung thư học ĐHYHN (Bài Ung thư khoang miệng - Ung thư lưỡi):\n1. Giải phẫu bệnh: Hơn 95% ung thư lưỡi là UNG THƯ BIỂU MÔ TẾ BÀO VẢY (Squamous cell carcinoma - SCC), vị trí hay gặp nhất là bờ bên 2/3 trước lưỡi (phần lưỡi di động).\n2. Di căn hạch: Do mạng lưới bạch huyết ở lưỡi rất phong phú và lưỡi co bóp liên tục khi nói, nhai, nuốt nên K lưỡi di căn hạch cổ rất sớm; chặng hạch đầu tiên thường bị di căn là HẠCH CỔ NHÓM I (nhóm dưới cằm IA, dưới hàm IB) và NHÓM II (dãy cảnh trên).\n3. Điều trị K lưỡi giai đoạn sớm (u kích thước ≤ 2 cm, độ sâu xâm lấn ≤ 5 mm, cT1N0M0): Phương pháp điều trị triệt căn chủ đạo là PHẪU THUẬT cắt rộng u (cắt hình chêm hoặc cắt nửa lưỡi đảm bảo diện cắt an toàn ≥ 1–1,5 cm) kết hợp vét hạch cổ chọn lọc (nhóm I, II, III) cùng bên (hoặc xạ trị áp sát bằng kim Iridium-192).",
