      "exp": "Theo Quyết định 183/QĐ-BYT năm 2022 của Bộ Y tế và Slide bài giảng Chăm sóc giảm nhẹ ĐHYHN (chụp tại tr.10 & tr.24 Tổng hợp RV):\n1. Về đối tượng cần Chăm sóc giảm nhẹ (Câu 2 tr.10): Dành cho người bệnh (người lớn và trẻ em) mắc các BỆNH NẶNG, NGHIÊM TRỌNG đe dọa tính mạng hoặc giới hạn sự sống (như ung thư, HIV/AIDS, suy tim, suy thận, COPD giai đoạn nặng...) gây ra các đau khổ về thể chất, tâm lý, xã hội.\n2. Về thời điểm thực hiện Chăm sóc giảm nhẹ (Câu 3 tr.10): Thực hiện NGAY TẠI THỜI ĐIỂM CHẨN ĐOÁN BỆNH UNG THƯ, lồng ghép đồng thời XUYÊN SUỐT QUÁ TRÌNH ĐIỀU TRỊ đặc hiệu, trở thành hình thức chăm sóc chính ở giai đoạn cuối đời và tiếp tục hỗ trợ tâm lý cho người nhà KHI BỆNH NHÂN QUA ĐỜI → Chọn 'D. Tất cả các ý trên'.",
