      "exp": "Theo Handout S3.7 Tập 1 (tr.20–21) và phân tích đề thi Đợt 2 K118 (tr.10 Tổng hợp RV):\n• Tiền gen sinh ung thư (Proto-oncogene) vốn là các gen bình thường trong tế bào có chức năng điều hòa sự tăng trưởng, phân chia và biệt hóa tế bào (mã hóa yếu tố tăng trưởng, thụ thể yếu tố tăng trưởng như EGFR/HER2, protein truyền tín hiệu nội bào như RAS, RAF, và yếu tố phiên mã nhân như MYC).\n• Khi các Proto-oncogene này bị đột biến (đột biến điểm, khuếch đại gen, chuyển đoạn nhiễm sắc thể) hoặc do VIRUS sinh ung thư chèn vào, chúng biến đổi thành Gen sinh ung thư (Oncogene) hoạt động theo cơ chế trội, thúc đẩy tế bào tăng sinh mất kiểm soát.\n• Lưu ý bẫy ở phương án B: Đề gài thêm chữ 'do VI KHUẨN hoặc virus xâm nhập vào' → SAI ở chữ 'vi khuẩn'!",
