      "q": "Câu 200 (Tổng hợp RV tr.11 - Đợt 2 K118 Câu 13). Trong các loại phẫu thuật điều trị tạm thời (phẫu thuật giảm nhẹ triệu chứng) ở bệnh nhân ung thư giai đoạn muộn, trường hợp nào sau đây là ví dụ điển hình của 'Phẫu thuật sạch sẽ' (Toilet / Sanitary surgery)?",
