      "exp": "Theo Handout S3.7 Tập 1 (Bài Đại cương phẫu thuật ung thư, tr.71) và đề thi Đợt 2 K118 (tr.11 Câu 13 Tổng hợp RV): Cần phân biệt rõ các phân nhóm nhỏ trong Phẫu thuật tạm thời (giảm nhẹ):\n• Phẫu thuật sạch sẽ (Toilet surgery): Điển hình nhất là cắt tuyến vú sạch sẽ ở bệnh nhân ung thư vú giai đoạn IV (đã di căn xương, phổi...) có khối u nguyên phát ở vú vỡ loét ra da, chảy máu, nhiễm trùng hoại tử gây mùi hôi nặng nề.\n• Phẫu thuật tái lập lưu thông (thông lưu): Mở thông dạ dày, nối vị tràng, làm hậu môn nhân tạo, mở khí quản, dẫn lưu đường mật.\nTrong đề thi (tr.11 Câu 13), cả 4 đáp án đều là phẫu thuật tạm thời nhưng đề hỏi đích danh 'Phẫu thuật sạch sẽ' nên đáp án chuẩn là A: Ung thư vú di căn xương vỡ loét!",
