      "hint": "Gợi ý: Trong đề thi K117 (tr.19 Câu 20 & tr.44 Câu 3): Hai phương án A ('Thời gian nhân đôi của các tế bào là tương đương nhau') và B ('Số tế bào chết nhiều hơn số tế bào tạo ra dẫn đến hoại tử u') đều là phương án bẫy SAI! Hãy chọn phương án mô tả sự mất cân bằng tăng sinh > chết tế bào / tăng sinh vượt quá khả năng cấp máu tân tạo mạch gây hoại tử trung tâm u.",
      "exp": "Theo Handout S3.7 Tập 1 (tr.8–9) và đính chính tại tr.19 Tổng hợp RV:\n1. Thời gian nhân đôi thể tích khối u (Tumor doubling time) RẤT KHÁC NHAU giữa các loại ung thư: rất ngắn ở U lympho Burkitt (~3 ngày), u tế bào mầm, K phổi tế bào nhỏ (~86 ngày), nhưng rất dài ở K đại trực tràng (~600 ngày) hay K vú → Do đó ý 'Thời gian nhân đôi tương đương nhau' là SAI.\n2. Để khối u phát triển tăng kích thước, tổng số tế bào sinh ra phải LỚN HƠN số tế bào chết đi. Hiện tượng hoại tử ở trung tâm khối u lớn là hậu quả của việc hệ thống mạch máu tân tạo (Angiogenesis) không phát triển kịp với tốc độ nhân lên của tế bào u gây thiếu oxy và chất dinh dưỡng ở lõi u, chứ KHÔNG phải do 'số tế bào chết nhiều hơn số tế bào tạo ra'.\n3. Về các mốc nhân đôi kinh điển: 1 tế bào ung thư nhân đôi 30 lần tạo ra $10^9$ tế bào (khối u đường kính ~1 cm, nặng ~1 gam — ngưỡng nhỏ nhất bắt đầu phát hiện được trên lâm sàng); nhân đôi 40 lần tạo ra $10^{12}$ tế bào (nặng ~1 kg — thường gây tử vong cho vật chủ).",
