      "q": "Câu 207 (Tổng hợp RV tr.42 - Câu 6). Theo Giáo trình Ung thư học Đại học Y Hà Nội (Handout S3.7 Tập 1 - Bài Đại cương xạ trị), dựa vào vị trí nguồn bức xạ so với cơ thể người bệnh, kỹ thuật xạ trị trong ung thư bao gồm các phương pháp nào?",
