      "hint": "Gợi ý: Trong bài Đại cương xạ trị ĐHYHN, mục các phương pháp xạ trị trình bày 3 kỹ thuật: (1) Xạ trị chiếu ngoài (nguồn xạ đặt ngoài cơ thể cách xa da 80–100 cm: máy gia tốc tuyến tính LINAC, Cobalt-60); (2) Xạ trị áp sát (nguồn xạ kín đặt áp sát bề mặt, trong hốc tự nhiên hoặc cắm vào mô u); (3) Xạ trị trong / chuyển hóa (dược chất phóng xạ nguồn hở đưa vào cơ thể qua đường uống hoặc tiêm tĩnh mạch như I-131 trong K giáp thể biệt hóa, P-32, Sr-89).",
      "exp": "Theo Handout S3.7 Tập 1 (Bài Đại cương xạ trị ung thư, tr.80–81): Có 3 phương thức kỹ thuật xạ trị lâm sàng được giảng dạy trong chương trình ĐHYHN:\n1. Xạ trị ngoài (External Beam Radiation Therapy): Nguồn bức xạ đặt ở ngoài cơ thể (máy gia tốc tuyến tính phát tia X năng lượng cao và chùm tia điện tử Electron, máy Cobalt-60 phát tia Gamma).\n2. Xạ trị áp sát (Brachytherapy): Sử dụng các nguồn phóng xạ kín (Ir-192, Cs-137) đặt vào các hốc tự nhiên (buồng tử cung - âm đạo, vòm mũi họng, thực quản), áp trên bề mặt hoặc cắm trực tiếp vào trong mô u (xạ trị trong mô như K lưỡi, K sàn miệng).\n3. Xạ trị trong / Xạ trị chuyển hóa (Metabolic / Systemic Radionuclide Therapy): Sử dụng đồng vị phóng xạ nguồn hở dưới dạng dung dịch uống hoặc tiêm tĩnh mạch để tập trung chọn lọc vào mô đích theo cơ chế chuyển hóa sinh học (điển hình là I-131 trong ung thư tuyến giáp thể biệt hóa, P-32, Sr-89/Sm-153 giảm đau di căn xương).",
      "ref_label": "Giáo trình Ung thư học Đại học Y Hà Nội (Handout Module S3.7 Tập 1 & Tập 2) & Tổng hợp Review S3.7 K117–K120"
