      "q": "Câu 208 (Tổng hợp RV tr.24 - Câu 18). Trong thực hành giao tiếp thông báo tin xấu (Breaking bad news - quy trình 6 bước SPIKES) cho bệnh nhân ung thư theo bài giảng Chăm sóc giảm nhẹ ĐHYHN, hành động hoặc nguyên tắc nào sau đây là KHÔNG ĐÚNG (câu hỏi TRỪ)?",
