      "q": "Câu 211 (Tổng hợp RV tr.29 - K Trực tràng Câu 2, Câu 3 & Câu 4). Khi nói về triệu chứng lâm sàng, chẩn đoán phân biệt và vai trò của Nội soi ống cứng trong Ung thư trực tràng theo Giáo trình Ung thư học ĐHYHN (tr.29 Tổng hợp RV), nhận định nào sau đây là ĐÚNG?",
