      "exp": "Theo Giáo trình Ung thư học ĐHYHN (Bài Ung thư đại trực tràng, chụp và chú giải tại tr.29 Tổng hợp RV):\n1. Đặc điểm lâm sàng (Câu 2 tr.29): Rối loạn lưu thông tiêu hóa và hội chứng trực tràng (mót rặn, cảm giác đi ngoài không hết phân, khuôn phân dẹt nhỏ như bút chì, ỉa máu tươi lẫn nhầy mũi) là dấu hiệu sớm báo động của Ung thư trực tràng. Lưu ý phân biệt: Ung thư đại tràng PHẢI thường thể sùi, lòng đại tràng rộng nên hay gây thiếu máu mạn tính, ỈA LỎNG và sờ thấy u hố chậu phải; còn Ung thư đại tràng TRÁI thường thể thâm nhiễm vòng nhẫn chít hẹp nên hay gây TÁO BÓN và BÁN TẮC / TẮC RUỘT.\n2. Đặc điểm của Nội soi ống cứng (Câu 3 tr.29): Nội soi ống cứng được áp dụng cho trực tràng và đoạn thấp đại tràng sigma (tới 20–25 cm), có ưu điểm vượt trội hơn ống mềm ở chỗ thước đo cứng không bị uốn cong nên ĐO ĐƯỢC CHÍNH XÁC KHOẢNG CÁCH từ bờ dưới khối u tới rìa hậu môn (thông số quyết định phẫu thuật cắt trước thấp bảo tồn cơ thắt hay phẫu thuật Miles!). Nội soi ống cứng chỉ nhìn bề mặt lòng ruột nên KHÔNG đánh giá được độ sâu xâm lấn thành trực tràng (phải dùng EUS hoặc MRI).\n3. Chẩn đoán phân biệt (Câu 4 tr.29): Đứng trước bệnh nhân đi ngoài ra máu tươi, chẩn đoán phân biệt quan trọng và dễ bị bỏ sót nhầm lẫn nhất trên lâm sàng là BỆNH TRĨ.",
