      "exp": "Theo Giáo trình Ung thư học Đại học Y Hà Nội (Mục 4.4.2 Phân độ mô học Ung thư đại trực tràng, chụp nguyên văn tại tr.29 Tổng hợp RV):\n• Biệt hóa cao (Well differentiated - G1): > 95% tế bào tạo cấu trúc ống tuyến.\n• Biệt hóa vừa (Moderately differentiated - G2): 50 – 95% tế bào tạo cấu trúc ống tuyến.\n• Kém biệt hóa (Poorly differentiated - G3): 5 – 50% tế bào tạo cấu trúc ống tuyến.\n• Không biệt hóa (Undifferentiated - G4): < 5% tế bào tạo cấu trúc ống tuyến.\n• Quy ước đặc biệt trong sách giáo khoa ĐHYHN: 'Ngoài ra, UNG THƯ BIỂU MÔ TUYẾN NHẦY và UNG THƯ BIỂU MÔ TẾ BÀO NHẪN được xếp loại như UNG THƯ BIỂU MÔ KÉM BIỆT HÓA (G3); còn ung thư biểu mô thể tủy có MSI-H được xếp loại ung thư biểu mô không biệt hóa (G4)'.",
