      "q": "Câu 214 (Tổng hợp RV tr.15 Câu 39 & tr.36 Câu 2 - Case UT vòm 1 Câu 2/2). [Bẫy phân độ N1 vs N2 cực hay] Trên bệnh nhân ở câu trên, kết quả sinh thiết vòm là Ung thư biểu mô vảy không sừng hóa, không biệt hóa. Chụp MRI đầu cổ ghi nhận: Khối u vòm xâm lấn xương nền sọ, có nhiều HẠCH SAU HẦU 2 BÊN và HẠCH CỔ BÊN PHẢI (1 bên) kích thước 3 cm, không có hạch hố thượng đòn, chưa di căn xa. Chẩn đoán giai đoạn TNM (AJCC) và hướng điều trị chuẩn cho bệnh nhân này là gì?",
