      "q": "Câu 215 (Tổng hợp RV tr.14 Câu 32–34 & tr.30 Case A). Trên bệnh nhân nữ 45 tuổi chẩn đoán Ung thư vú đã phẫu thuật cắt tuyến vú + vét hạch nách, giải phẫu bệnh sau mổ: độ mô học 3, di căn 10/12 hạch nách (+), thụ thể nội tiết ER/PR (-), HER2/NEU (+++): (1) Trong các yếu tố của bệnh nhân này, yếu tố nào KHÔNG PHẢI là yếu tố tiên lượng xấu? (2) Sau điều trị một thời gian, bệnh nhân xuất hiện tái phát hạch thượng đòn cùng bên đơn độc, hướng điều trị tiếp theo là gì?",
