      "hint": "Gợi ý: Xem chú thích viết tay cực chuẩn trên trang 30 Tổng hợp RV: (1) Ở câu 2: 'Tuổi > 45 → đây là yếu tố nguy cơ, không phải yếu tố tiên lượng xấu' (trong khi Di căn 10/12 hạch, Thụ thể nội tiết âm tính, Độ mô học 3 và HER2 3+ đều là yếu tố tiên lượng xấu!); (2) Ở câu 3: Khi xuất hiện hạch thượng đòn cùng bên, vì bệnh nhân có Thụ thể nội tiết (-) và HER2 (+++) nên phải chọn 'B. Hóa xạ + điều trị đích' (gạch bỏ phương án C và D vì có chữ nội tiết!).",
      "exp": "Theo Handout S3.7 Tập 2 (Bài Ung thư vú, ảnh chụp slide Hóa mô miễn dịch tại tr.30 Tổng hợp RV) và Quyết định 3128/QĐ-BYT:\n1. Các yếu tố tiên lượng xấu của Ung thư vú gồm: Kích thước u lớn, di căn nhiều hạch nách (ở đây là 10/12 hạch - pN3a), độ mô học cao (Độ 3), xâm nhập mạch máu - bạch huyết, thụ thể nội tiết âm tính (ER-, PR-), bộc lộ quá mức HER2/neu (3+), chỉ số Ki-67 cao, và tuổi trẻ (< 35 tuổi). Ngược lại, tuổi ≥ 45 tuổi là yếu tố nguy cơ mắc K vú chứ KHÔNG phải yếu tố tiên lượng xấu.\n2. Khi bệnh nhân K vú có ER/PR (-), HER2 (+++) xuất hiện tái phát hạch thượng đòn cùng bên (cN3c): Phác đồ điều trị chuẩn là phối hợp HÓA - XẠ TRỊ tại vùng kết hợp ĐIỀU TRỊ ĐÍCH kháng HER2 (Trastuzumab ± Pertuzumab). Tuyệt đối không chọn các đáp án có 'điều trị nội tiết' vì thụ thể nội tiết của bệnh nhân âm tính.",
      "ref_label": "Quyết định 3128/QĐ-BYT năm 2020 của Bộ Y tế (Hướng dẫn chẩn đoán và điều trị Ung thư vú)",
