      "q": "Câu 216 (Tổng hợp RV tr.30–31 - K Vú Câu 1 & Câu 2). Khi nói về chặng hạch bạch huyết và xét nghiệm Tế bào học trong chẩn đoán Ung thư vú theo Giáo trình Ung thư học ĐHYHN (tr.30–31 Tổng hợp RV), cặp nhận định nào sau đây là ĐÚNG?",
