      "hint": "Gợi ý: Xem ảnh chụp trang sách giáo khoa ĐHYHN trên trang 31 Tổng hợp RV (Mục 3.2. Tế bào học): 'Tế bào học là một trong 3 phương pháp chẩn đoán xác định bệnh ung thư vú. Chọc hút khối u, hạch nách bằng kim nhỏ hoặc lấy dịch tiết núm vú tìm tế bào ác tính' → Chọn D. Tất cả các ý trên!",
      "exp": "Theo Giáo trình Ung thư học Đại học Y Hà Nội (Bài Ung thư vú, chụp tại tr.30–31 Tổng hợp RV):\n1. Về hệ thống bạch huyết của tuyến vú: Bạch huyết của tuyến vú đổ về 3 hướng chính là: (a) Nhóm hạch nách cùng bên (nhận ~75% bạch huyết của vú, gồm 3 tầng I, II, III và nhóm hạch gian cơ ngực nằm giữa cơ ngực lớn và cơ ngực bé gọi là hạch Rotter); (b) Nhóm hạch vú trong (dọc theo bó mạch ngực trong); và (c) Nhóm hạch dưới đòn - thượng đòn cùng bên. Trong đề trắc nghiệm (tr.30–31 Câu 1), phương án 'D. Hạch Turrez' là đáp án NGOẠI TRỪ (hoặc nếu đề chỉ có Hạch nách, Hạch vú trong, Hạch thượng đòn cùng bên và Hạch Troisier thì chọn Hạch Troisier vì hạch Troisier là hạch thượng đòn trái di căn từ K dạ dày/ổ bụng qua ống ngực).\n2. Về xét nghiệm Tế bào học trong K vú (Câu 2 tr.31): Bệnh phẩm làm tế bào học gồm cả 3 nguồn: (a) Chọc hút tế bào khối u vú bằng kim nhỏ (FNA u vú); (b) Chọc hút tế bào hạch nách bằng kim nhỏ; (c) Áp lam / phết chất dịch tiết núm vú tìm tế bào ác tính → Chọn 'D. Tất cả các ý trên'.",
