      "exp": "Theo Handout S3.7 Tập 2 (Bài Ung thư vú, tổng hợp tại tr.31–32 Tổng hợp RV) và Quyết định 3128/QĐ-BYT:\n1. Các chỉ định của Xạ trị bổ trợ trong Ung thư vú (liều 45–50 Gy + boost diện u):\n• Tất cả các trường hợp sau phẫu thuật bảo tồn tuyến vú.\n• Sau phẫu thuật cắt tuyến vú triệt căn có nguy cơ tái phát tại chỗ - tại vùng cao: Khối u T3 (> 5 cm) hoặc T4 (xâm lấn thành ngực/da), có di căn hạch nách, diện cắt phẫu thuật dương tính hoặc sát u, độ mô học III, xâm lấn mạch máu - bạch huyết (LVSI +), u đa ổ.\n• Do đó, 'D. Thụ thể nội tiết âm tính' là đáp án NGOẠI TRỪ trong Câu 3 tr.31.\n2. Khuyến cáo sàng lọc K vú theo nhóm tuổi (Bảng tr.32 Tổng hợp RV):\n• Từ 40–49 tuổi: Tự khám vú 1 lần/tháng sau sạch kinh 5 ngày.\n• Từ ≥ 50 tuổi: Tự khám vú 1 lần/tháng sau sạch kinh 5 ngày; khám lâm sàng chuyên khoa định kỳ 1 LẦN/NĂM và chụp X-quang tuyến vú sàng lọc 1–2 năm/lần (đặc biệt 1 lần/năm ở nhóm nguy cơ cao).",
