      "q": "Câu 218 (Tổng hợp RV tr.32 - Case B K vú di căn não Câu 1/3). Bệnh nhân nữ 45 tuổi vào viện vì Ung thư vú đã có di căn não, kích thước khối u vú nguyên phát là 3 cm, độ mô học 3, thụ thể nội tiết âm tính. Hỏi: (1) Khối u vú kích thước 3 cm của bệnh nhân thuộc mức T mấy, và theo phân loại TNM thì khối u mức T3 trong ung thư vú có kích thước là bao nhiêu? (2) Trong các thông tin của bệnh nhân (Di căn, Tuổi 45, Thụ thể âm tính, Kích thước u 3 cm), đâu KHÔNG phải là yếu tố nguy cơ gây bệnh ung thư vú?",
