      "q": "Câu 219 (Tổng hợp RV tr.32 - Case B K vú di căn não Câu 2/3). Trên bệnh nhân nữ 45 tuổi Ung thư vú nghi ngờ có di căn não, các phương pháp chẩn đoán hình ảnh nào sau đây được chỉ định để xác định tổn thương di căn não (và phương pháp nào KHÔNG dùng)?",
