      "q": "Câu 220 (Tổng hợp RV tr.32 - Case B K vú di căn não Câu 3/3). Đối với bệnh nhân nữ 45 tuổi Ung thư vú đã có di căn não, độ mô học 3, thụ thể nội tiết âm tính (ER-, PR-) nêu trên, hướng điều trị phù hợp là gì (lưu ý loại trừ các phương án có điều trị nội tiết)?",
