      "correct_idx": 0,
      "ans": "A. Phối hợp Hóa trị toàn thân và Xạ trị não (Trong 4 phương án A, B, C, D ở tr.32, cả 3 phương án A, C, D đều sai vì có chữ 'Điều trị nội tiết' trong khi đề bài đã cho 'thụ thể nội tiết âm tính', nên chọn B: Hóa - Xạ trị!)",
      "hint": "Gợi ý: Nhìn vào 4 đáp án của Câu 4 trang 32 Tổng hợp RV: A. Hóa chất + điều trị nội tiết / B. Hóa xạ trị đồng thời (phối hợp Hóa trị và Xạ trị) / C. Hóa chất + phẫu thuật + xạ bổ trợ + nội tiết / D. Xạ trị + điều trị nội tiết. Vì đề bài cho rõ 'thụ thể nội tiết ÂM TÍNH' nên A, C, D đều bị loại ngay lập tức, chỉ còn duy nhất đáp án B!",
      "exp": "Theo Quyết định 3128/QĐ-BYT và phân tích câu hỏi tại tr.32 Tổng hợp RV:\n• Bệnh nhân ung thư vú giai đoạn IV có di căn não và thụ thể nội tiết âm tính (ER-, PR-) cần được điều trị phối hợp giữa kiểm soát tại chỗ ди căn não (Xạ trị toàn não WBRT hoặc Xạ phẫu định vị SRS ± phẫu thuật thần kinh nếu ổ đơn độc lớn, kèm Corticoid Dexamethason chống phù não) và điều trị toàn thân bằng Hóa chất (± Đích/Miễn dịch).\n• Vì khối u có thụ thể nội tiết âm tính nên bệnh nhân KHÔNG có chỉ định điều trị nội tiết → Loại trừ ngay 3 phương án A, C, D (đều chứa 'điều trị nội tiết'), đáp án đúng là B (phối hợp Hóa trị và Xạ trị).",
      "ref_label": "Quyết định 3128/QĐ-BYT năm 2020 của Bộ Y tế (Hướng dẫn chẩn đoán và điều trị Ung thư vú)",
