      "q": "Câu 221 (Tổng hợp RV tr.34 K CTC Câu 2 & tr.35 K Vòm Câu 1). (1) Trong điều trị Ung thư cổ tử cung giai đoạn sớm (IA2 – IB1 – IIA1), phẫu thuật triệt căn Wertheim - Meigs (cắt tử cung rộng, cắt parametrium, 1/3 trên âm đạo và vét hạch chậu) có thể gặp các biến chứng nào (và biến chứng nào KHÔNG thể xảy ra)? (2) Khi chẩn đoán Ung thư vòm mũi họng / đầu cổ, cần làm thêm thăm dò nội soi nào để sàng lọc tìm ung thư nguyên phát thứ 2 đồng thời?",
