      "hint": "Gợi ý: Xem ghi chú viết tay trên trang 34 Câu 2 ('dây chằng' — cắt rộng dây chằng rộng/parametrium sát niệu quản và đám rối thần kinh hạ vị gây biến chứng chảy máu, nhiễm trùng, tổn thương niệu quản và đờ bàng quang/bí tiểu; còn tử cung đã cắt bỏ nên không có 'đờ tử cung'!).",
      "exp": "Theo Giáo trình Ung thư học ĐHYHN (tổng hợp tại tr.34–35 Tổng hợp RV):\n1. Về Phẫu thuật Wertheim - Meigs trong K cổ tử cung (Câu 2 tr.34): Là phẫu thuật lớn cắt bỏ toàn bộ tử cung mở rộng, phần trên âm đạo, tổ chức cạnh tử cung (parametrium) và vét hạch chậu hai bên. Các biến chứng trong và sau mổ gồm: Chảy máu trong mổ (tổn thương tĩnh mạch chậu), Nhiễm trùng vết mổ/tiểu khung, Tổn thương niệu quản - bàng quang (gây rò niệu quản - âm đạo, rò bàng quang - âm đạo), Rối loạn chức năng bàng quang (bàng quang thần kinh gây bí tiểu/mất cảm giác buồn tiểu do cắt dây thần kinh tự chủ vùng chậu), và Tụ dịch bạch huyết (Lymphocele) / phù bạch mạch chi dưới. Lưu ý: Nếu câu hỏi hỏi biến chứng hay gặp thì chú ý Nhiễm trùng / Chảy máu / Rò tiết niệu; nếu câu hỏi hỏi 'Biến chứng của PT Wertheim-Meigs, TRỪ?' thì chọn 'B. Đờ tử cung' (vì tử cung đã được cắt bỏ!).\n2. Về sàng lọc ung thư nguyên phát thứ 2 khi chẩn đoán K vòm / K đầu cổ (Câu 1 tr.35): Do hiện tượng 'ung thư hóa vùng niêm mạc' (Field cancerization) của đường hô hấp - tiêu hóa trên, cần kết hợp nội soi tai mũi họng kỹ và nội soi thực quản - dạ dày để không bỏ sót tổn thương đồng mắc.",
      "ref_label": "Quyết định 2402/QĐ-BYT & Giáo trình Ung thư học Đại học Y Hà Nội",
