      "correct_idx": 2,
      "ans": "C. Ung thư vòm mũi họng (Lưu ý: Với biến thể đề K118 đợt 2 có cả A. K vòm mũi họng và B. U lympho Burkitt thì cả hai bệnh này đều liên quan mật thiết với EBV; trong đó K vòm mũi họng là ung thư biểu mô phổ biến nhất tại Việt Nam liên quan đến EBV).",
      "hint": "Gợi ý (Lec 2: Nguyên nhân và cơ chế): Đối chiếu chuẩn kiến thức Lec 2: Nguyên nhân và cơ chế ĐHYHN. Đáp án chuẩn: C. Ung thư vòm mũi họng (Lưu ý: Với biến thể đề K118 đợt 2 có cả A. K vòm mũi họng và B. U lympho Burkitt thì .",
      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nTheo Giáo trình Ung thư học ĐHYHN (Bài 2: Nguyên nhân và cơ chế sinh ung thư - mục Tác nhân sinh học & Bài Ung thư vòm mũi họng), virus Epstein-Barr (EBV - thuộc họ Herpesviridae, HHV-4) là tác nhân sinh ung thư đường sinh học đã được chứng minh có mối liên quan căn nguyên chặt chẽ với:\n1. **Ung thư vòm mũi họng (Nasopharyngeal carcinoma - NPC)**, đặc biệt là thể ung thư biểu mô vảy không sừng hóa, không biệt hóa (WHO type III - phổ biến nhất tại miền Bắc Việt Nam và Nam Trung Quốc). Bộ gen của EBV và các kháng nguyên virus (EBNA-1, LMP-1, LMP-2) hiện diện trong hầu hết các tế bào u vòm mũi họng, đồng thời kháng thể IgA/VCA và IgA/EA hoặc tải lượng EBV-DNA huyết tương tăng cao có giá trị sàng lọc, chẩn đoán và theo dõi điều trị.\n2. **U lympho Burkitt (Burkitt lymphoma)** thể dịch tễ ở trẻ em châu Phi.\n3. Một số u lympho Hodgkin và u lympho ở người suy giảm miễn dịch.\nTrong 4 phương án A (hạ họng), B (thanh quản), C (vòm mũi họng), D (thực quản), chỉ có Ung thư vòm mũi họng liên quan trực tiếp đến EBV.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- A. Ung thư hạ họng (SAI): Ung thư hạ họng chủ yếu liên quan đến hai yếu tố nguy cơ chính có tác dụng hiệp đồng là hút thuốc lá và uống rượu mạnh kéo dài, cùng hội chứng Plummer-Vinson. Phương án A sẽ ĐÚNG khi hỏi về ung thư vùng đầu cổ liên quan chặt chẽ đến nghiện rượu và thuốc lá.\n- B. Ung thư thanh quản (SAI): Ung thư thanh quản liên quan hàng đầu đến hút thuốc lá (chiếm >85-90% trường hợp), tiếp xúc bụi amiăng, hơi hóa chất và một phần nhỏ HPV. Phương án B sẽ ĐÚNG khi hỏi về ung thư đường hô hấp trên có mối liên hệ nhân quả mạnh nhất với khói thuốc lá.\n- D. Ung thư thực quản (SAI): Ung thư thực quản 1/3 trên và 1/3 giữa (thể vảy) liên quan đến rượu, thuốc lá, thói quen ăn uống quá nóng, chất nitrosamine; 1/3 dưới (thể tuyến) liên quan đến trào ngược dạ dày-thực quản (GERD) và thực quản Barrett. Phương án D sẽ ĐÚNG khi hỏi về ung thư phát sinh trên nền tổn thương thực quản Barrett.\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K117 - đợt 1):\nCâu hỏi gốc đầy đủ 4 phương án A, B, C, D (và có thêm biến thể đề K118 trong phần ghi chú). Không cần sửa câu hỏi gốc. Đáp án VẪN GIỮ NGUYÊN là C (Ung thư vòm mũi họng)."
