      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nTheo Giáo trình Ung thư học ĐHYHN (Bài 2: Nguyên nhân và cơ chế sinh ung thư - mục Thuốc lá), thuốc lá là nguyên nhân gây ung thư và tử vong có thể phòng tránh được lớn nhất trên thế giới (chiếm khoảng 30% tổng số tử vong do ung thư). Trong khói thuốc lá chứa hơn **4.000 - 7.000 hóa chất độc hại**, trong đó có tới **hơn 60 - 70 chất đã được chứng minh là tác nhân gây ung thư (carcinogens)** trên người và thực nghiệm — bao gồm các hydrocarbon thơm đa vòng (tiêu biểu là 3,4-benzopyrene), các hợp chất N-nitrosamine đặc hiệu thuốc lá (TSNAs), các amin thơm (2-naphthylamine, 4-aminobiphenyl), benzen, формаldehyde, cùng các kim loại nặng và chất phóng xạ (Polonium-210, Cadmium, Arsenic, Nickel). Do đó, phát biểu nói trong thuốc lá 'CHỈ CÓ 1 chất sinh ung thư là 3,4-benzopyrene' là hoàn toàn SAI.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- B. Còn gây ra nhiều bệnh ung thư khác: phế quản phổi, thanh quản, thực quản, họng miệng (SAI vì đây là phát biểu đúng): Ngoài chiếm ~85-90% nguyên nhân ung thư phổi, khói thuốc lá còn gây ung thư khoang miệng, hạ họng, thanh quản, thực quản, bàng quang, thận, tụy, dạ dày, cổ tử cung. Phương án B sẽ ĐÚNG khi hỏi về phổ các bệnh ung thư liên quan đến thuốc lá.\n- C. Là nguyên nhân tử vong hàng đầu (SAI vì đây là phát biểu đúng): Thuốc lá là tác nhân hàng đầu gây tử vong do ung thư (chiếm khoảng 30% tổng số ca tử vong do ung thư). Phương án C sẽ ĐÚNG khi hỏi về tác nhân ngoại sinh gây tử vong do ung thư đứng hàng đầu.\n- D. Ngoài ung thư còn gây nhiều bệnh khác (SAI vì đây là phát biểu đúng): Thuốc lá còn là nguyên nhân chính gây bệnh phổi tắc nghẽn mạn tính (COPD), bệnh mạch vành, đột quỵ não và bệnh mạch máu ngoại vi.\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K118 - đợt 1):\nCâu hỏi gốc đầy đủ 4 phương án A, B, C, D. Không cần chỉnh sửa. Đáp án VẪN GIỮ NGUYÊN là A."
