      "correct_idx": 1,
      "ans": "B. K phổi (nếu câu hỏi là 'Không hút thuốc lá là biện pháp dự phòng cấp 1 hiệu quả nhất cho ung thư nào?'). Lưu ý: Nếu câu hỏi gốc có chữ 'TRỪ' ('Không hút thuốc lá giúp dự phòng được các ung thư sau, TRỪ:') thì đáp án đúng là D. U lympho Hodgkin.",
      "hint": "Gợi ý (Lec 2: Nguyên nhân và cơ chế): Đối chiếu chuẩn kiến thức Lec 2: Nguyên nhân và cơ chế ĐHYHN. Đáp án chuẩn: B. K phổi (nếu câu hỏi là 'Không hút thuốc lá là biện pháp dự phòng cấp 1 hiệu quả nhất cho ung thư nào?'). Lư.",
      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nTheo Giáo trình Ung thư học ĐHYHN (Bài 2: Nguyên nhân sinh ung thư & Bài 4: Dự phòng ung thư):\n- Khói thuốc lá (chủ động và thụ động) là nguyên nhân hàng đầu gây **ung thư phế quản - phổi** (chiếm 85 - 90% tổng số ca bệnh; người hút thuốc lá có nguy cơ mắc K phổi gấp 10 - 30 lần người không hút). Do đó, không hút thuốc lá và cai thuốc lá là biện pháp dự phòng bước 1 (dự phòng nguyên phát) đặc hiệu và hiệu quả nhất để giảm tỷ lệ mắc ung thư phổi.\n- Ngoài ung thư phổi, các chất chuyển hóa của khói thuốc lá (như hydrocarbon thơm đa vòng, nitrosamine, các amin thơm 2-naphthylamine đào thải qua nước tiểu) còn gây **ung thư thực quản** (A/C) và **ung thư bàng quang** (A).\n- Ngược lại, **U lympho Hodgkin (D)** có nguyên nhân liên quan đến nhiễm virus Epstein-Barr (EBV), yếu tố di truyền và suy giảm miễn dịch, chứ không phải là bệnh ung thư đặc trưng do thuốc lá gây ra. Vì vậy nếu đề gốc có chữ 'TRỪ' thì đáp án là D (U lympho Hodgkin); còn nếu hỏi ung thư điển hình nhất dự phòng được nhờ không hút thuốc lá thì đáp án là B (K phổi).\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- A. K bàng quang: Các chất sinh ung thư trong khói thuốc lá (đặc biệt là các amin thơm như 2-naphthylamine, 4-aminobiphenyl) được lọc qua thận và tích tụ trong nước tiểu tại bàng quang, gây tổn thương ADN biểu mô chuyển tiếp. Hút thuốc lá chiếm khoảng 50% nguyên nhân K bàng quang.\n- C. K thực quản: Khói thuốc lá nuốt cùng nước bọt và tiếp xúc niêm mạc thực quản (đặc biệt khi hiệp đồng với rượu bia) làm tăng nguy cơ ung thư biểu mô vảy thực quản gấp nhiều lần.\n- D. U lympho Hodgkin: Là bệnh ác tính hệ tạo huyết - hạch bạch huyết có tế bào Reed-Sternberg đặc trưng, liên quan đến EBV chứ không phải bệnh ung thư do thuốc lá; phương án D ĐÚNG khi đề hỏi 'Không hút thuốc lá giúp dự phòng các bệnh ung thư sau, TRỪ:'.\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K118 - đợt 3):\nCâu hỏi gốc có 4 phương án A. K bàng quang, B. K phổi, C. K thực quản, D. U lympho Hodgkin. Trong bài giảng ĐHYHN (Lec 2 & Lec 4), hút thuốc lá là nguyên nhân gây K phổi (chiếm ~85-90%), K thực quản và K bàng quang (chiếm ~40-50%), trong khi U lympho Hodgkin KHÔNG liên quan trực tiếp đến thuốc lá như các ung thư biểu mô kể trên. Vì vậy, có 2 khả năng của đề thi gốc: (Khả năng 1): Đề hỏi 'Không hút thuốc lá là biện pháp dự phòng cấp 1 quan trọng nhất đối với bệnh ung thư nào?' -> Chọn B (K phổi - vì thuốc lá chiếm tới 85-90% nguyên nhân K phổi). (Khả năng 2): Đề hỏi 'Không hút thuốc lá giúp dự phòng được các bệnh ung thư nào sau đây, TRỪ:' -> Chọn D (U lympho Hodgkin). Đã ghi chú rõ cả 2 trường hợp trong phần hiệu đính và đáp án để bao quát tuyệt đối."
