      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nTheo Giáo trình Ung thư học ĐHYHN (Bài 3: Dịch tễ học ung thư - mục Tình hình ung thư tại Việt Nam), dữ liệu ghi nhận ung thư quần thể giữa hai miền Nam - Bắc (tiêu biểu là Ghi nhận ung thư Hà Nội và Ghi nhận ung thư TP. Hồ Chí Minh) ở phụ nữ Việt Nam có quy luật phân bố địa dư rất đặc trưng:\n- **Ung thư vú (B)**: Là ung thư phổ biến hàng đầu ở nữ giới, có tỷ lệ mắc ở **miền Bắc (Hà Nội) cao hơn miền Nam (TP.HCM)**.\n- **Ung thư cổ tử cung (A)**: Có tỷ lệ mắc ở **miền Nam (TP.HCM) cao hơn rõ rệt so với miền Bắc (Hà Nội)** (gấp khoảng 2 - 3 lần ở giai đoạn trước khi phổ cập sàng lọc).\n- **Ung thư phổi (D)**: Là một trong 5 loại ung thư phổ biến nhất ở nữ giới trên phạm vi **toàn quốc**.\n- Ngược lại, **KHÔNG có quy luật dịch tễ nào nói 'Ung thư buồng trứng thường gặp ở miền Trung'** trong giáo trình và dữ liệu ghi nhận ung thư Việt Nam. Do đó, phương án **C** là phát biểu sai và là đáp án cần chọn.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- A. K cổ tử cung thường gặp ở miền Nam (SAI vì là phát biểu đúng): Theo số liệu ghi nhận ung thư tại Việt Nam trong giáo trình ĐHYHN, ở phụ nữ miền Nam (TP.HCM), ung thư cổ tử cung có tỷ lệ chuẩn theo tuổi (ASR) cao vượt trội so với phụ nữ miền Bắc.\n- B. K vú thường gặp ở miền Bắc (SAI vì là phát biểu đúng): Ở phụ nữ miền Bắc (Hà Nội), ung thư vú đứng số 1 với tỷ lệ cao hơn so với khu vực phía Nam.\n- D. K phổi gặp ở phụ nữ toàn quốc (SAI vì là phát biểu đúng): Ung thư phổi nằm trong nhóm các ung thư phổ biến ở cả nam và nữ trên phạm vi toàn quốc (liên quan đến hút thuốc lá thụ động và ô nhiễm không khí).\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K118 - đợt 3):\nCâu hỏi gốc đầy đủ 4 phương án A, B, C, D. Không cần chỉnh sửa. Đáp án VẪN GIỮ NGUYÊN là C."
