      "topic": "Lec 6: Nguyên tắc điều trị",
      "q": "Câu 259 (Câu 38 - K117 - đợt 1). BN điều trị hóa chất được 2 chu kỳ thì có hạ bạch cầu độ 4. Bác sĩ thêm chỉ định dùng thuốc dự phòng hạ bạch cầu từ chu kỳ 3. Đây là nguyên tắc nào trong điều trị ung thư?",
