      "hint": "Gợi ý (Lec 6: Nguyên tắc điều trị): Đối chiếu chuẩn kiến thức Lec 6: Nguyên tắc điều trị ĐHYHN. Đáp án chuẩn: B. Theo dõi, dự phòng và xử trí kịp thời các tác dụng không mong muốn / biến chứng của điều trị (Điều trị hỗ t.",
      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nTheo Giáo trình Ung thư học ĐHYHN (Bài 6: Nguyên tắc điều trị ung thư & Bài 9: Các phương pháp điều trị nội khoa), nôn và buồn nôn do hóa chất (Chemotherapy-Induced Nausea and Vomiting - CINV) là một trong những tác dụng không mong muốn cấp tính thường gặp nhất do hóa chất kích thích các tế bào ưa bạc (enterochromaffin cells) ở niêm mạc đường tiêu hóa giải phóng serotonin (5-HT) hoạt hóa dây thần kinh phế vị và vùng nhận cảm hóa học gây nôn (CTZ) tại sàn não thất IV. Việc bác sĩ theo dõi và sử dụng thuốc chống nôn (như nhóm đối kháng thụ thể 5-HT3 Ondansetron, Palonosetron kết hợp Dexamethasone, Aprepitant...) trước và sau truyền hóa chất thuộc về nguyên tắc **Theo dõi, dự phòng và xử trí kịp thời các tai biến, tác dụng phụ của điều trị (điều trị hỗ trợ)** nhằm giúp bệnh nhân dung nạp được phác đồ và đảm bảo chất lượng sống.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- A. Lập kế hoạch điều trị (SAI): Lập kế hoạch điều trị là việc hội chẩn lựa chọn các mô thức đặc hiệu (phẫu thuật, xạ trị, hóa trị), thứ tự phối hợp và phác đồ thuốc chống u dựa trên chẩn đoán giai đoạn TNM, mô bệnh học và thể trạng bệnh nhân trước khi bắt đầu điều trị.\n- C. Phối hợp điều trị đa mô thức (SAI): Điều trị đa mô thức là sự kết hợp các phương pháp điều trị đặc hiệu chống khối u (như Phẫu thuật + Hóa trị + Xạ trị), không phải là việc dùng thuốc giảm triệu chứng nôn do hóa chất.\n- D. Xác định mục đích điều trị (SAI): Là việc xác định điều trị triệt căn hay điều trị tạm thời ngay từ trước khi can thiệp.\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K118 - đợt 1):\nCâu hỏi gốc chỉ có 2 phương án a, b (tương tự cấu trúc câu 38). Phục dựng đầy đủ 4 phương án theo đúng bài giảng Lec 6 (Nguyên tắc điều trị ung thư - ĐHYHN):\nA. Lập kế hoạch điều trị\nB. Theo dõi và xử trí kịp thời các tác dụng không mong muốn / biến chứng của điều trị (điều trị hỗ trợ)\nC. Phối hợp điều trị đa mô thức\nD. Xác định rõ mục đích điều trị\nĐáp án VẪN GIỮ NGUYÊN là B."
