      "q": "Câu 271 (Câu 50 - K118 - đợt 2). Phẫu thuật nào sau đây là phẫu thuật sạch sẽ: k nhớ mấy đáp còn lại nhưng mấy đáp đó nó thuộc phẫu thuật tạm thời",
