      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nTheo Giáo trình Ung thư học ĐHYHN (Bài 8: Xạ trị trong ung thư - mục Tai biến và biến chứng của xạ trị), mô da và niêm mạc nằm trong trường chiếu xạ là các mô lành có tốc độ đổi mới tế bào nhanh (mô đáp ứng sớm), nên rất nhạy cảm với tia xạ. Mức độ tổn thương da và niêm mạc do tia xạ (từ ban đỏ da, sạm da, bong vảy khô đến bong vảy ướt, loét hoại tử da; hoặc viêm đỏ niêm mạc miệng-họng đến loét giả mạc) **phụ thuộc trực tiếp vào tổng liều xạ (total dose), phân liều mỗi ngày (dose per fraction) và thể tích trường chiếu** (hiệu ứng xác định - deterministic effect có ngưỡng liều). Liều xạ càng cao thì mức độ viêm da, viêm niêm mạc càng nặng.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- A. Máy gia tốc an toàn nên không có rò phóng xạ (SAI): Mặc dù máy gia tốc tuyến tính (LINAC) an toàn hơn nguồn phóng xạ tự nhiên Cobalt-60 (vì chỉ phát tia khi bật nguồn điện), nhưng trong khi máy đang phát tia vẫn có bức xạ thứ cấp/bức xạ rò và tán xạ, đòi hỏi phòng máy (bunker) phải có tường chì/bê tông cốt thép dày che chắn và tuân thủ nghiêm ngặt quy tắc an toàn bức xạ.\n- B. Biến chứng xạ trị thường xuất hiện sau khoảng 2-3 tháng (SAI): Các phản ứng/biến chứng cấp tính của xạ trị trên mô lành phân chia nhanh (viêm da, viêm niêm mạc, rụng tóc, buồn nôn, tiêu chảy) thường bắt đầu xuất hiện sớm sau khoảng **2 - 3 tuần** kể từ khi bắt đầu chiếu xạ (tương đương mức liều tích lũy 20 - 30 Gy), chứ không phải đợi đến 2-3 tháng. (Còn biến chứng muộn như xơ hóa mô dưới da, hoại tử xương hàm, viêm phổi/viêm trực tràng do xạ thường xuất hiện sau **6 tháng đến nhiều năm**).\n- C. Biến chứng xạ trị chỉ xảy ra tại chỗ tại vùng (SAI): Ngoài các biến chứng tại chỗ - tại vùng trong trường chiếu, xạ trị còn gây ra các **rối loạn/biến chứng toàn thân** như mệt mỏi, chán ăn, buồn nôn - nôn (nhất là khi chiếu vùng bụng hoặc sọ não), và **ức chế tủy xương (hạ bạch cầu, tiểu cầu, thiếu máu)** khi chiếu xạ vào các vùng xương dẹt chứa nhiều tủy tạo máu (xương chậu, cột sống, xương ức).\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K117 - đợt 1):\nCâu hỏi gốc đầy đủ 4 phương án A, B, C, D. Không cần chỉnh sửa. Đáp án VẪN GIỮ NGUYÊN là D."
