      "correct_idx": 3,
      "ans": "D. U vú (nếu giữ nguyên 4 phương án A. U lympho không Hodgkin, B. U vòm, C. U tinh hoàn, D. U vú — vì A, B, C đều rất nhạy cảm với tia xạ, còn K tuyến vú chỉ nhạy cảm trung bình). Lưu ý: Nếu phương án D trong đề gốc là U hắc tố / Ung thư tuyến giáp / Sarcoma xương / Schwannoma (như ghi chú bài giảng) thì chọn D vì đó là nhóm u kháng tia xạ điển hình.",
      "hint": "Gợi ý (Lec 8: Xạ trị): Đối chiếu chuẩn kiến thức Lec 8: Xạ trị ĐHYHN. Đáp án chuẩn: D. U vú (nếu giữ nguyên 4 phương án A. U lympho không Hodgkin, B. U vòm, C. U tinh hoàn, D. U vú — vì A, B, C .",
      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nTheo Giáo trình Ung thư học ĐHYHN (Bài 8: Xạ trị trong ung thư - mục Độ nhạy cảm phóng xạ của các mô và khối u - Định luật Bergonié và Tribondeau), độ nhạy cảm với tia xạ tỷ lệ thuận với tốc độ phân bào và tỷ lệ nghịch với mức độ biệt hóa của tế bào. Trên lâm sàng, các khối u được chia thành 3 nhóm:\n1. **Nhóm rất nhạy cảm với tia xạ (Radiosensitive)** (liều diệt u 25 - 45 Gy): **U lympho Hodgkin và không Hodgkin (A)**, bệnh bạch cầu, **U tinh bào của tinh hoàn (Seminoma - C)**, u nguyên bào tủy, u Wilms.\n2. **Nhóm nhạy cảm trung bình với tia xạ (Moderately radiosensitive)** (liều diệt u 50 - 70 Gy): Các ung thư biểu mô vảy vùng đầu cổ (đặc biệt **Ung thư vòm mũi họng - B** thể không biệt hóa rất nhạy cảm với tia xạ nên xạ trị là phương pháp triệt căn chủ đạo), ung thư cổ tử cung, **ung thư biểu mô tuyến vú (D)** (nhạy cảm kém hơn so với u lympho, u tinh bào và K vòm), ung thư phổi.\n3. **Nhóm ít nhạy cảm / kháng tia xạ (Radioresistant)** (liều cần > 70 Gy vượt quá sức chịu đựng của mô lành): **Ung thư tế bào hắc tố (Melanoma)**, **Sarcoma xương**, **Sarcoma phần mềm**, **U bao dây thần kinh (Schwannoma)**, **Ung thư tuyến giáp** (đối với xạ trị chiếu ngoài), ung thư tế bào thận.\nDo đó, trong 4 phương án A, B, C, D của câu hỏi, **D** là đáp án đúng.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- A. U lympho không Hodgkin (SAI): Thuộc nhóm khối u nhạy cảm cao nhất với tia xạ (chỉ cần 30 - 40 Gy đã tiêu diệt được u).\n- B. U vòm mũi họng (SAI): Đặc biệt thể carcinoma không sừng hóa, không biệt hóa (type III) rất nhạy cảm với tia xạ, giúp xạ trị đạt tỷ lệ kiểm soát tại chỗ >85-90% ở giai đoạn sớm.\n- C. U tinh hoàn (U tinh bào - Seminoma) (SAI): Là một trong những khối u đặc nhạy cảm nhất với tia xạ (chỉ cần liều 20 - 30 Gy).\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K118 - đợt 1):\nCâu hỏi gốc trong review có 4 phương án (a. u lympho không Hodgkin; b. u vòm; c. u tinh hoàn; d. u vú) nhưng chưa điền đáp án và có ghi chú: 'Không nhạy cảm: giáp trạng, schwannoma, hắc tố, xương'. Phân tích hiệu đính: Trong bài giảng Xạ trị (Lec 8 - ĐHYHN), các khối u được phân loại theo độ nhạy cảm với tia xạ thành:\n1. **Nhóm rất nhạy cảm với tia xạ**: U lympho (Hodgkin và không Hodgkin - A), U tinh bào tinh hoàn (Seminoma - C), u nguyên bào thần kinh, u nguyên bào thận (Wilms).\n2. **Nhóm nhạy cảm trung bình với tia xạ**: Ung thư biểu mô vảy (như Ung thư vòm mũi họng - B, đặc biệt K vòm thể không biệt hóa lại rất nhạy xạ), Ung thư biểu mô tuyến vú (D), K cổ tử cung, K phổi.\n3. **Nhóm ít nhạy cảm / kháng tia xạ (radioresistant)**: Sarcoma xương, sarcoma phần mềm, u tế bào hắc tố (Melanoma), u thần kinh (Schwannoma/Glioblastoma), ung thư tuyến giáp (với xạ chiếu ngoài).\nNhư vậy, trong 4 phương án A (U lympho không Hodgkin), B (U vòm), C (U tinh hoàn), D (U vú):\n- Nếu câu hỏi gốc có 4 phương án là A, B, C, D như trên thì **D. Ung thư vú (ung thư biểu mô tuyến)** có độ nhạy cảm tia xạ THẤP NHẤT trong 4 loại này (vì A, B, C đều rất nhạy xạ, còn K tuyến vú nhạy cảm trung bình/kém hơn). \n- Còn nếu phương án D trong đề gốc thực chất là **D. U hắc tố / Ung thư tuyến giáp / Sarcoma xương** (như trong dòng Note của sinh viên) thì D là khối u kháng xạ điển hình. Đã ghi rõ cả hai trường hợp trong đáp án."
