      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nTheo Giáo trình Ung thư học ĐHYHN (Bài 9: Các phương pháp điều trị nội khoa ung thư), các thuốc hóa trị kinh điển thuộc nhóm thuốc **gây độc tế bào (cytotoxic drugs)** (B). Khi đi vào tế bào đang phân chia, thuốc tác động qua các cơ chế: gây tổn thương và **đứt gãy phân tử ADN** hoặc ức chế tổng hợp ADN/ARN (A), ức chế quá trình hình thành và hoạt động của thoi vô sắc, từ đó **làm ngừng chu kỳ tế bào** tại các pha tương ứng (pha S, pha G2 hoặc pha M) (C) và dẫn đến chết tế bào theo chương trình (apoptosis). Vì vậy, cả 3 phương án A, B, C đều đúng.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- A, B, C (SAI nếu chọn đơn lẻ): Mỗi phương án chỉ nêu một phần trong chuỗi cơ chế tác dụng của hóa chất chống ung thư, nên chọn D (Cả 3) là chính xác nhất.\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K117 - đợt 2):\nCâu hỏi gốc đầy đủ 4 phương án A, B, C, D. Hiệu đính lỗi chính tả đánh máy ('A. Gây đứt gãy ADN; B. Gây độc tế bào; C. Ngừng chu kỳ tế bào; D. Cả 3'). Đáp án VẪN GIỮ NGUYÊN là D."
