      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nTheo Giáo trình Ung thư học ĐHYHN (Bài 10: Chăm sóc giảm nhẹ cho bệnh nhân ung thư - mục Khi nào cần chăm sóc giảm nhẹ?), mô hình tích hợp chăm sóc giảm nhẹ hiện đại của WHO quy định chăm sóc giảm nhẹ phải được thực hiện liên tục qua toàn bộ các mốc thời gian:\n1. **Bắt đầu ngay từ khi chẩn đoán xác định bệnh ung thư (b)**: Giúp thông báo tin xấu đúng nguyên tắc, nâng đỡ tâm lý và kiểm soát ngay các triệu chứng do khối u gây ra.\n2. **Xuyên suốt trong toàn bộ quá trình điều trị đặc hiệu (c)**: Phối hợp song hành cùng phẫu thuật, xạ trị, hóa trị để kiểm soát đau và các tác dụng không mong muốn của điều trị (nôn, hạ bạch cầu, viêm niêm mạc, suy kiệt...).\n3. **Giai đoạn cuối đời và sau khi bệnh nhân qua đời (a)**: Trở thành phương thức chăm sóc chính yếu khi điều trị đặc hiệu không còn hiệu quả, giúp bệnh nhân ra đi thanh thản không đau đớn và **tiếp tục chăm sóc hỗ trợ tang chế cho gia đình sau khi bệnh nhân qua đời**.\nDo đó, đáp án **D (Tất cả các ý trên)** là hoàn toàn chính xác.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- A, B, C (SAI nếu chỉ chọn đơn lẻ): Mỗi phương án chỉ nêu một giai đoạn trong chuỗi liên tục (continuum) của chăm sóc giảm nhẹ toàn diện.\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K118 - đợt 2):\nCâu hỏi gốc đầy đủ 4 phương án a, b, c, d. Không cần chỉnh sửa. Đáp án VẪN GIỮ NGUYÊN là D."
