      "part_title": "PHẦN VIII: BỘ CÂU HỎI & CASE LÂM SÀNG REVIEW S3.7 K117–K118 THEO BÀI GIẢNG (123 CÂU)",
      "topic": "Lec 11: Điều trị đau",
      "q": "Câu 311 (Câu 90 - K118 - đợt 3). Ung thư giai đoạn cuối sử dụng morphin để điều trị triệu chứng gì:\n1. Buồn nôn\n2. Lo âu\n3. Khó thở\n4. Táo bón",
