      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nTheo Giáo trình Ung thư học ĐHYHN (Bài CBA 2: Ung thư vòm mũi họng - mục Giải phẫu bệnh theo phân loại của Tổ chức Y tế Thế giới WHO), ung thư biểu mô vòm mũi họng (Nasopharyngeal carcinoma - NPC) được chia thành 3 type mô bệnh học chính:\n- **Type I**: Ung thư biểu mô vảy sừng hóa (Keratinizing squamous cell carcinoma) — chiếm tỷ lệ thấp tại Việt Nam (< 5%), ít liên quan EBV và ít nhạy cảm với tia xạ hơn.\n- **Type II**: Ung thư biểu mô vảy không sừng hóa, thể biệt hóa (Non-keratinizing differentiated carcinoma) — chiếm khoảng 10 - 15%.\n- **Type III**: **Ung thư biểu mô vảy không sừng hóa, thể không biệt hóa (Undifferentiated carcinoma of nasopharyngeal type - UCNT)** — là thể mô bệnh học **PHỔ BIẾN NHẤT tại Việt Nam và các vùng dịch tễ Đông Nam Á / Nam Trung Quốc (chiếm tới 80 - 85% tổng số ca bệnh)**, có mối liên hệ chặt chẽ nhất với nhiễm virus **EBV** và **rất nhạy cảm với tia xạ cũng như hóa chất**.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- A. Vảy sừng hóa (WHO type I) (SAI): Tại Việt Nam thể vảy sừng hóa rất ít gặp (< 5%); phương án A chỉ ĐÚNG ở các vùng không lưu hành dịch tễ (như Bắc Mỹ, châu Âu) nơi K vòm chủ yếu liên quan đến thuốc lá và rượu.\n- B. Vảy không sừng hóa thể biệt hóa (WHO type II) (SAI): Chỉ đứng thứ hai (khoảng 10 - 15%), ít gặp hơn nhiều so với thể không biệt hóa (type III).\n- D. Ung thư biểu mô tuyến (SAI): Rất hiếm gặp ở vòm mũi họng (thường gặp ở hốc mũi và các xoang cạnh mũi hơn).",
