      "vignette": "Bệnh nhân nam 50 tuổi vào viện vì đau nửa đầu phải, ù tai phải và nhìn đôi. Khám lâm sàng phát hiện mắt phải lác trong (tổn thương dây thần kinh sọ số VI), sờ thấy 01 hạch cổ bên phải kích thước 1 cm. Nội soi và chụp MRI vòm mũi họng thấy khối u vòm xâm lấn hố dưới thái dương và nền sọ, chưa có di căn xa.",
